begin;
    with j as (select * from jsonb_to_recordset($law7v004$[{"code_id":"APK_RF","article_number":"308.7","version_date":"2002-07-24","article_text":"1. В определении судьи Верховного Суда Российской Федерации о передаче надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации должны быть указаны:\n\n1) дата и место вынесения определения;\n\n2) фамилия и инициалы судьи, вынесшего определение;\n\n3) наименование лица, подавшего надзорные жалобу, представление;\n\n4) сведения об обжалуемых судебных актах;\n\n5) содержание дела, по которому приняты обжалуемые судебные акты;\n\n6) основания передачи надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации;\n\n7) предложения судьи, вынесшего определение.\n\n2. Судья Верховного Суда Российской Федерации передает вынесенное им определение, а также надзорные жалобу, представление вместе с делом в Президиум Верховного Суда Российской Федерации.","article_title":"Статья 308.7. Определение о передаче надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"10e33ad98c3bf9808404ce78172ac55c4102d9b8000743acff37e442d59023b2"},{"code_id":"APK_RF","article_number":"308.8","version_date":"2002-07-24","article_text":"Судебные постановления, указанные в части 3 статьи 3081 настоящего Кодекса, подлежат отмене или изменению, если при рассмотрении дела в порядке надзора Президиум Верховного Суда Российской Федерации установит, что соответствующее обжалуемое судебное постановление нарушает:\n\n1) права и свободы человека и гражданина, гарантированные Конституцией Российской Федерации, общепризнанными принципами и нормами международного права, международными договорами Российской Федерации;\n\n2) права и законные интересы неопределенного круга лиц или иные публичные интересы;\n\n3) единообразие в применении и (или) толковании судами норм права.","article_title":"Статья 308.8. Основания для отмены или изменения судебных постановлений в порядке надзора","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b1800ef6869386870c9f2da3cbca9daf1ec913416277ba5b89b7ab7bc3cfbca6"},{"code_id":"APK_RF","article_number":"308.9","version_date":"2002-07-24","article_text":"1. Президиум Верховного Суда Российской Федерации принимает дело к рассмотрению на основании определения судьи Верховного Суда Российской Федерации о передаче надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации.\n\n2. Президиум Верховного Суда Российской Федерации направляет лицам, участвующим в деле, копии определения о передаче надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации и копии надзорных жалобы, представления. Время рассмотрения надзорных жалобы, представления вместе с делом в Президиуме Верховного Суда Российской Федерации назначается с учетом того, чтобы лица, участвующие в деле, имели возможность явиться в судебное заседание.\n\n3. Лица, участвующие в деле, извещаются о времени и месте рассмотрения дела Президиумом Верховного Суда Российской Федерации. Неявка указанных лиц, надлежащим образом извещенных о времени и месте рассмотрения дела Президиумом Верховного Суда Российской Федерации, не препятствует рассмотрению дела в порядке надзора.\n\n4. Председатель Верховного Суда Российской Федерации или заместитель Председателя Верховного Суда Российской Федерации, вынесшие определение о передаче надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации, не могут участвовать в рассмотрении Президиумом Верховного Суда Российской Федерации данных надзорных жалобы, представления вместе с делом.\n\n5. Надзорные жалоба, представление вместе с делом рассматриваются Президиумом Верховного Суда Российской Федерации в судебном заседании в срок, не превышающий двух месяцев со дня вынесения судьей определения.\n\n6. В судебном заседании могут принимать участие лица, участвующие в деле, их представители, иные лица, подавшие надзорные жалобу, представление, если их права и законные интересы непосредственно затрагиваются обжалуемым судебным актом. Указанные лица могут участвовать в судебном заседании путем использования систем видеоконференц-связи в порядке, установленном статьей 1531 настоящего Кодекса.\n\n7. В случае, если прокурор является лицом, участвующим в рассмотрении дела, в судебном заседании Президиума Верховного Суда Российской Федерации принимает участие Генеральный прокурор Российской Федерации или заместитель Генерального прокурора Российской Федерации.\n\n8. Надзорные жалоба, представление вместе с делом, рассматриваемые в порядке надзора Президиумом Верховного Суда Российской Федерации, докладываются судьей Верховного Суда Российской Федерации - докладчиком по данным жалобе, представлению.\n\n9. Судья-докладчик излагает обстоятельства дела, содержание судебных постановлений, принятых по делу, доводы, содержащиеся в надзорных жалобе, представлении и послужившие основанием для передачи надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации.\n\n10. Лица, указанные в части 6 настоящей статьи и явившиеся в судебное заседание, вправе дать объяснения по делу. Первым дает объяснения лицо, подавшее надзорные жалобу, представление.\n\n11. По результатам рассмотрения надзорных жалобы, представления вместе с делом Президиум Верховного Суда Российской Федерации принимает постановление.\n\n12. Вопросы, возникающие при рассмотрении надзорных жалобы, представления вместе с делом в порядке надзора, разрешаются судьями большинством голосов. При равном числе голосов, поданных за пересмотр дела и против его пересмотра, надзорные жалоба, представление считаются отклоненными.\n\n13. О принятом Президиумом Верховного Суда Российской Федерации в порядке надзора постановлении сообщается лицам, участвующим в деле.","article_title":"Статья 308.9. Порядок и срок рассмотрения надзорных жалобы, представления вместе с делом в судебном заседании Президиума Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0ff75026cb8d61dc552589b9c79b1a3742d7354c11426b85b31a5afca0f5bfce"},{"code_id":"APK_RF","article_number":"309","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 23.12.2010 № 379-ФЗ)\n\nАрбитражный суд может пересмотреть принятый им и вступивший в законную силу судебный акт по новым или вновь открывшимся обстоятельствам по основаниям и в порядке, которые предусмотрены в настоящей главе. (В редакции Федерального закона от 23.12.2010 № 379-ФЗ)","article_title":"Статья 309. Право арбитражного суда пересмотреть судебный акт по новым или вновь открывшимся обстоятельствам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"302b895adcf1697609f21bdb62924054eefc25b4d7804268de8307f4c3e09bdd"},{"code_id":"APK_RF","article_number":"31","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\nАрбитражные суды рассматривают в соответствии с главой 30 настоящего Кодекса дела:\n\n1) об оспаривании решений третейских судов по спорам, возникающим при осуществлении предпринимательской и иной экономической деятельности;\n\n2) о выдаче исполнительных листов на принудительное исполнение решений третейских судов по спорам, возникающим при осуществлении предпринимательской и иной экономической деятельности;\n\n3) об оказании содействия третейским судам по спорам, возникающим при осуществлении предпринимательской и иной экономической деятельности.\n\n(Статья в редакции Федерального закона от 29.12.2015 № 409-ФЗ)","article_title":"Статья 31. Компетенция арбитражных судов по делам, связанным с выполнением арбитражными судами функций содействия и контроля в отношении третейских судов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1995f1b93235ad8be2cfb6d3724efe4317697228531676ba574a7827e7272433"},{"code_id":"APK_RF","article_number":"310","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 23.12.2010 № 379-ФЗ)","article_title":"Статья 310. Арбитражные суды, пересматривающие судебные акты по новым или вновь открывшимся обстоятельствам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1d0f26d9b6abb45c695dda3a2053fda3aafcd29f2e6544ccde517cdd3020fc91"},{"code_id":"APK_RF","article_number":"311","version_date":"2002-07-24","article_text":"1. Основаниями пересмотра судебных актов по правилам настоящей главы являются:\n\n1) вновь открывшиеся обстоятельства - указанные в части 2 настоящей статьи и существовавшие на момент принятия судебного акта обстоятельства по делу;\n\n2) новые обстоятельства - указанные в части 3 настоящей статьи, возникшие после принятия судебного акта, но имеющие существенное значение для правильного разрешения дела обстоятельства.\n\n2. Вновь открывшимися обстоятельствами являются:\n\n1) существенные для дела обстоятельства, которые не были и не могли быть известны заявителю;\n\n2) установленные вступившим в законную силу приговором суда фальсификация доказательства, заведомо ложное заключение эксперта, заведомо ложные показания свидетеля, заведомо неправильный перевод, которые повлекли за собой принятие незаконного или необоснованного судебного акта по данному делу;\n\n3) установленные вступившим в законную силу приговором суда преступные деяния лица, участвующего в деле, или его представителя либо преступные деяния судьи, совершенные при рассмотрении данного дела.\n\n21. Обстоятельства, указанные в пунктах 2 и 3 части 2 настоящей статьи, могут быть установлены помимо приговора постановлением об отказе в возбуждении уголовного дела, определением или постановлением о прекращении уголовного дела или уголовного преследования, вынесенными:\n\n1) в связи с истечением срока давности;\n\n2) в связи с устранением преступности и наказуемости деяния новым уголовным законом;\n\n3) в связи с возмещением ущерба;\n\n4) в связи с назначением меры уголовно-правового характера в виде судебного штрафа;\n\n5) в связи с применением принудительных мер воспитательного воздействия;\n\n6) в связи с применением принудительных мер медицинского характера;\n\n7) в связи со смертью обвиняемого;\n\n8) в связи с недостижением лицом возраста, с которого наступает уголовная ответственность, или отставанием несовершеннолетнего в психическом развитии, не связанном с психическим расстройством;\n\n9) в связи с деятельным раскаянием;\n\n10) в связи с примирением сторон;\n\n11) в связи с освобождением от уголовной ответственности на основании части первой статьи 781 Уголовного кодекса Российской Федерации;\n\n12) в связи с применением акта об амнистии.\n\n(Дополнение частью - Федеральный закон от 15.12.2025 № 485-ФЗ)\n\n3. Новыми обстоятельствами являются:\n\n1) отмена судебного акта арбитражного суда или суда общей юрисдикции либо постановления другого органа, послуживших основанием для принятия судебного акта по данному делу;\n\n2) признанная вступившим в законную силу судебным актом арбитражного суда или суда общей юрисдикции недействительной сделка, которая повлекла за собой принятие незаконного или необоснованного судебного акта по данному делу;\n\n3) признание постановлением Конституционного Суда Российской Федерации не соответствующим Конституции Российской Федерации или применение в истолковании, расходящемся с данным Конституционным Судом Российской Федерации в постановлении истолкованием, примененного арбитражным судом в судебном акте нормативного акта либо его отдельного положения в связи с обращением заявителя, а в случаях, предусмотренных Федеральным конституционным законом от 21 июля 1994 года № 1-ФКЗ \"О Конституционном Суде Российской Федерации\", в связи с обращением иного лица независимо от обращения заявителя в Конституционный Суд Российской Федерации; (В редакции Федерального закона от 30.12.2021 № 473-ФЗ)\n\n4) (Пункт утратил силу - Федеральный закон от 11.06.2022 № 183-ФЗ)\n\n5) определение либо изменение в постановлении Пленума Верховного Суда Российской Федерации или в постановлении Президиума Верховного Суда Российской Федерации практики применения правовой нормы, если в соответствующем акте Верховного Суда Российской Федерации содержится указание на возможность пересмотра вступивших в законную силу судебных актов в силу данного обстоятельства; (В редакции Федерального закона от 28.06.2014 № 186-ФЗ)\n\n6) установление или изменение федеральным законом оснований признания здания, сооружения или другого строения самовольной постройкой, послуживших основанием для принятия судебного акта о сносе самовольной постройки. (Дополнение пунктом - Федеральный закон от 03.08.2018 № 340-ФЗ)\n\n(Статья в редакции Федерального закона от 23.12.2010 № 379-ФЗ)","article_title":"Статья 311. Основания пересмотра судебных актов по новым или вновь открывшимся обстоятельствам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"90e81882ec4a11848359dea85be7a9de33949a484f681d37e59bd5f9da8cd09c"},{"code_id":"APK_RF","article_number":"312","version_date":"2002-07-24","article_text":"В случае, если наличие обстоятельства, предусмотренного пунктом 5 части 3 статьи 311 настоящего Кодекса, выявлено при рассмотрении кассационных жалобы, представления или надзорных жалобы, представления, указанный трехмесячный срок исчисляется со дня размещения определения об отказе в передаче кассационных жалобы, представления для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации, определения об отказе в передаче надзорных жалобы, представления для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации в информационно-телекоммуникационной сети \"Интернет\".\n\n(Часть в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n(Статья в редакции Федерального закона от 23.12.2010 № 379-ФЗ)","article_title":"Статья 312. Порядок и срок подачи заявления о пересмотре судебного акта по новым или вновь открывшимся обстоятельствам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"358dbe801bb4e7bf019835d9a664d3b731c9f095b25c82a4132c03edaceb8c6b"},{"code_id":"APK_RF","article_number":"313","version_date":"2002-07-24","article_text":"1) наименование арбитражного суда, в который подается заявление;\n\n2) наименования лица, подающего заявление, и других лиц, участвующих в деле, их адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) наименование арбитражного суда, принявшего судебный акт, о пересмотре которого по новым или вновь открывшимся обстоятельствам ходатайствует заявитель; номер дела, дата принятия судебного акта; предмет спора; (В редакции Федерального закона от 23.12.2010 № 379-ФЗ)\n\n4) требование лица, подающего заявление; новое или вновь открывшееся обстоятельство, предусмотренное статьей 311 настоящего Кодекса и являющееся, по мнению заявителя, основанием для постановки вопроса о пересмотре судебного акта по новым или вновь открывшимся обстоятельствам, со ссылкой на документы, подтверждающие открытие или установление этого обстоятельства; (В редакции Федерального закона от 23.12.2010 № 379-ФЗ)\n\n5) перечень прилагаемых документов.\n\nВ заявлении могут быть также указаны номера телефонов, факсов, адреса электронной почты лиц, участвующих в деле, и иные сведения.\n\nЗаявление и прилагаемые к нему документы в электронном виде направляются лицам, участвующим в деле, посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. (Дополнение абзацем - Федеральный закон от 30.12.2021 № 440-ФЗ)\n\n1) копии документов, подтверждающих новые или вновь открывшиеся обстоятельства; (В редакции Федерального закона от 23.12.2010 № 379-ФЗ)\n\n2) копия судебного акта, о пересмотре которого ходатайствует заявитель;\n\n3) документ, подтверждающий направление другим лицам, участвующим в деле, копий заявления и документов, которые у них отсутствуют;\n\n4) доверенность или иной документ, подтверждающие полномочия лица на подписание заявления.","article_title":"Статья 313. Форма и содержание заявления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"89aeb638564b63f433bd1c373da5b897e1b67830cddeed75d95e36c19d86e984"},{"code_id":"APK_RF","article_number":"314","version_date":"2002-07-24","article_text":"В случае нарушения указанных требований арбитражный суд возвращает заявление в порядке, предусмотренном статьей 315 настоящего Кодекса.\n\nО принятии заявления к производству арбитражный суд выносит определение.\n\nВ определении указываются время и место проведения судебного заседания по рассмотрению заявления.\n\nКопии определения направляются лицам, участвующим в деле.","article_title":"Статья 314. Принятие заявления к производству арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4c3d2d96b661a01e2aaccd4ce21cc6b02618679f4ab392dc8d0a4039e7663732"},{"code_id":"APK_RF","article_number":"315","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 23.12.2010 № 379-ФЗ)\n\n1) заявление подано с нарушением правил, установленных статьей 310 настоящего Кодекса;\n\n2) заявление подано после истечения установленного срока и отсутствует ходатайство о его восстановлении или в восстановлении пропущенного срока подачи заявления отказано;\n\n3) не соблюдены требования, предъявляемые настоящим Кодексом к форме и содержанию заявления.\n\nКопия определения направляется заявителю вместе с заявлением и прилагаемыми к нему документами не позднее следующего дня после дня его вынесения.","article_title":"Статья 315. Возвращение заявления о пересмотре судебного акта по новым или вновь открывшимся обстоятельствам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b6deee67f48c2baa0ac768b9113cb57fc1a0cac40b318f6e8d5d9ad62699192b"},{"code_id":"APK_RF","article_number":"316","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 23.12.2010 № 379-ФЗ)","article_title":"Статья 316. Рассмотрение заявления о пересмотре судебного акта по новым или вновь открывшимся обстоятельствам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1d0f26d9b6abb45c695dda3a2053fda3aafcd29f2e6544ccde517cdd3020fc91"},{"code_id":"APK_RF","article_number":"317","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 23.12.2010 № 379-ФЗ)\n\nьи 311 настоящего Кодекса, судебный акт, принятый в результате повторного рассмотрения дела, не может быть изменен в сторону ухудшения положения лица, привлекаемого или привлеченного к ответственности за административные или налоговые правонарушения либо к иной публично-правовой ответственности. (Дополнение частью - Федеральный закон от 23.12.2010 № 379-ФЗ)\n\nРАЗДЕЛ VII. ПРОИЗВОДСТВО ПО ДЕЛАМ, СВЯЗАННЫМ С ИСПОЛНЕНИЕМ СУДЕБНЫХ АКТОВ АРБИТРАЖНЫХ СУДОВ","article_title":"Статья 317. Судебные акты, принимаемые арбитражным судом по результатам рассмотрения заявления о пересмотре судебного акта по новым или вновь открывшимся обстоятельствам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8099bf47a67e9501f2839b93fb63e7646f872577331ca1174bcad718fc9bce21"},{"code_id":"APK_RF","article_number":"318","version_date":"2002-07-24","article_text":"1. Судебные акты арбитражных судов приводятся в исполнение после вступления их в законную силу, за исключением случаев немедленного исполнения, в порядке, установленном настоящим Кодексом и иными федеральными законами, регулирующими вопросы исполнительного производства.\n\n2. Принудительное исполнение судебного акта производится на основании выдаваемого арбитражным судом исполнительного листа, если иное не предусмотрено настоящим Кодексом.","article_title":"Статья 318. Порядок исполнения судебных актов арбитражных судов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b22e2ce2a73047d7ba372553523631cd7b3fbc27a5178240b6cf0aef8af1ecb"},{"code_id":"APK_RF","article_number":"319","version_date":"2002-07-24","article_text":"Выдача судебного приказа для исполнения осуществляется по правилам, предусмотренным главой 291 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 02.03.2016 № 47-ФЗ)\n\n(Часть в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\nИсполнительный лист по решению о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок направляется на исполнение арбитражным судом в пятидневный срок со дня принятия решения независимо от наличия ходатайства об этом взыскателя. (Дополнение абзацем - Федеральный закон от 30.04.2010 № 69-ФЗ)\n\nИсполнительный лист может направляться судом для исполнения в форме электронного документа, подписанного судьей усиленной квалифицированной электронной подписью в порядке, установленном законодательством Российской Федерации. (Дополнение абзацем - Федеральный закон от 08.03.2015 № 41-ФЗ)","article_title":"Статья 319. Выдача исполнительного листа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2795503fcb7b5e289b946df5819a4479899817b68a92b1f3153a2e859d4c181c"},{"code_id":"APK_RF","article_number":"32","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\nАрбитражные суды рассматривают в соответствии с главой 31 настоящего Кодекса дела о признании и приведении в исполнение решений иностранных судов и иностранных арбитражных решений по спорам, возникающим при осуществлении предпринимательской и иной экономической деятельности.","article_title":"Статья 32. Компетенция арбитражных судов по делам о признании и приведении в исполнение решений иностранных судов и иностранных арбитражных решений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2df625eac5856743686c53e3e73d705c79adc7d0dc7ac0fc548e62b2527a688b"},{"code_id":"APK_RF","article_number":"320","version_date":"2002-07-24","article_text":"1. В исполнительном листе должны быть указаны:\n\n1) наименование арбитражного суда, выдавшего исполнительный лист; наименование и место нахождения иностранного суда, третейского суда или международного коммерческого арбитража, если исполнительный лист выдан арбитражным судом на основании решения такого суда;\n\n2) дело, по которому выдан исполнительный лист, и номер дела;\n\n3) дата принятия судебного акта, подлежащего исполнению;\n\n4) сведения о взыскателе: для гражданина-взыскателя - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, серия и номер водительского удостоверения); для организации-взыскателя - наименование, адрес, идентификационный номер налогоплательщика; сведения о должнике: для гражданина-должника - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, место работы (если известно), один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, основной государственный регистрационный номер индивидуального предпринимателя, серия и номер водительского удостоверения); для организации-должника - наименование, адрес, идентификационный номер налогоплательщика и основной государственный регистрационный номер; (В редакции Федерального закона от 21.12.2021 № 417-ФЗ)\n\n5) резолютивная часть судебного акта;\n\n6) дата вступления судебного акта в законную силу либо требование о его немедленном исполнении; (В редакции Федерального закона от 02.10.2007 № 225-ФЗ)\n\n7) дата выдачи исполнительного листа и срок предъявления его к исполнению;\n\n8) реквизиты банковского счета взыскателя, на который должны быть перечислены средства, подлежащие взысканию, в случае присуждения компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок. (Дополнение пунктом - Федеральный закон от 30.04.2010 № 69-ФЗ) (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\nЕсли до выдачи исполнительного листа арбитражным судом предоставлена отсрочка или рассрочка исполнения судебного акта, в исполнительном листе указывается, с какого времени начинается течение срока действия исполнительного листа.\n\n2. Исполнительный лист подписывается судьей и заверяется гербовой печатью арбитражного суда.","article_title":"Статья 320. Содержание исполнительного листа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"71d9bd2d72ba770f5bb34971eb3b503191e352070a59fb3343b6badfe6e25910"},{"code_id":"APK_RF","article_number":"321","version_date":"2002-07-24","article_text":"1. Исполнительный лист может быть предъявлен к исполнению в следующие сроки:\n\n1) в течение трех лет со дня вступления судебного акта в законную силу, или со следующего дня после дня принятия судебного акта, подлежащего немедленному исполнению, или со дня окончания срока, установленного при отсрочке или рассрочке исполнения судебного акта;\n\n2) в течение трех месяцев со дня вынесения определения о восстановлении пропущенного срока для предъявления исполнительного листа к исполнению в соответствии со статьей 322 настоящего Кодекса.\n\n2. В случае, если исполнение судебного акта было приостановлено, время, на которое исполнение приостанавливалось, не засчитывается в срок, установленный для предъявления исполнительного листа к исполнению.\n\n3. Срок предъявления исполнительного листа к исполнению прерывается предъявлением его к исполнению, если федеральным законом не установлено иное, частичным исполнением судебного акта.\n\n4. В случае возвращения исполнительного листа взыскателю в связи с невозможностью его исполнения новый срок для предъявления исполнительного листа к исполнению исчисляется со дня его возвращения.","article_title":"Статья 321. Сроки предъявления исполнительного листа к исполнению","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1d639f2a6589ab9228bfb5b9de526e2416aa08679f1edc0ebda0ae6316be6677"},{"code_id":"APK_RF","article_number":"322","version_date":"2002-07-24","article_text":"1. Взыскатель, пропустивший срок для предъявления исполнительного листа к исполнению, вправе обратиться в арбитражный суд первой инстанции, рассматривавший дело, с заявлением о восстановлении пропущенного срока, если восстановление указанного срока предусмотрено федеральным законом.\n\n2. Заявление взыскателя о восстановлении пропущенного срока рассматривается в порядке, предусмотренном статьей 117 настоящего Кодекса. По результатам рассмотрения заявления выносится определение.\n\nКопии определения направляются взыскателю и должнику.\n\n3. Определение арбитражного суда по вопросу о восстановлении пропущенного срока для предъявления исполнительного листа к исполнению может быть обжаловано.","article_title":"Статья 322. Восстановление пропущенного срока для предъявления исполнительного листа к исполнению","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aba707f6aa43260c0bf276c2ff714f511d8b4be5430601d49a5ddea2d157dca1"},{"code_id":"APK_RF","article_number":"324","version_date":"2002-07-24","article_text":"1. При наличии обстоятельств, затрудняющих исполнение судебного акта, арбитражный суд, выдавший исполнительный лист, по заявлению взыскателя, должника или судебного пристава-исполнителя вправе отсрочить или рассрочить исполнение судебного акта, изменить способ и порядок его исполнения.\n\n2. Заявление об отсрочке или о рассрочке исполнения судебного акта, об изменении способа и порядка его исполнения рассматривается арбитражным судом в месячный срок со дня поступления заявления в арбитражный суд в судебном заседании с извещением взыскателя, должника и судебного пристава-исполнителя. Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения заявления.\n\nПо результатам рассмотрения заявления выносится определение.\n\nКопии определения направляются взыскателю, должнику и судебному приставу-исполнителю.\n\n3. В случае предоставления должнику отсрочки или рассрочки исполнения судебного акта арбитражный суд вправе по заявлению взыскателя принять меры по обеспечению исполнения судебного акта по правилам, установленным главой 8 настоящего Кодекса.\n\n4. Определение арбитражного суда об отсрочке или о рассрочке исполнения судебного акта, об изменении способа и порядка его исполнения либо об отказе в удовлетворении заявления об отсрочке или о рассрочке исполнения судебного акта, об изменении способа и порядка его исполнения может быть обжаловано.","article_title":"Статья 324. Отсрочка или рассрочка исполнения судебного акта, изменение способа и порядка его исполнения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"81561a7284bf3b4af27b3acc2cd4db9098e9c7a9656948882d717fc34db07e14"},{"code_id":"APK_RF","article_number":"325","version_date":"2002-07-24","article_text":"1. Если приведенный в исполнение судебный акт отменен полностью или в части и принят новый судебный акт о полном или частичном отказе в иске, либо иск оставлен без рассмотрения, либо производство по делу прекращено, ответчику возвращается все то, что было взыскано с него в пользу истца по отмененному или измененному в соответствующей части судебному акту.\n\n2. Если не приведенный в исполнение судебный акт отменен полностью или в части и принят новый судебный акт о полном или частичном отказе в иске, либо иск оставлен без рассмотрения полностью или в части, либо производство по делу прекращено, арбитражный суд принимает судебный акт о полном или частичном прекращении взыскания по отмененному в соответствующей части судебному акту.","article_title":"Статья 325. Поворот исполнения судебного акта","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"02729b18cd77192440f380fd0f76b48ebc6004fcc05d8926a5c91d00220f4b92"},{"code_id":"APK_RF","article_number":"326","version_date":"2002-07-24","article_text":"1. Вопрос о повороте исполнения судебного акта разрешается арбитражным судом, принявшим новый судебный акт, которым отменен или изменен ранее принятый судебный акт.\n\n2. Если в постановлении об отмене или изменении судебного акта нет указаний на поворот его исполнения, ответчик вправе подать соответствующее заявление в арбитражный суд первой инстанции.\n\n3. Заявление о повороте исполнения судебного акта рассматривается в порядке, предусмотренном статьей 324 настоящего Кодекса.\n\n4. Определение арбитражного суда о повороте исполнения судебного акта или об отказе в повороте исполнения может быть обжаловано.\n\n5. Арбитражный суд первой инстанции выдает исполнительный лист на возврат взысканных денежных средств, имущества или его стоимости по заявлению организации, гражданина. К заявлению прилагается документ, подтверждающий исполнение ранее принятого судебного акта.","article_title":"Статья 326. Разрешение вопроса о повороте исполнения судебного акта","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ba87dde823901f1d6661377e798253e9d706c14abf3e210389518611e371c8bb"},{"code_id":"APK_RF","article_number":"327","version_date":"2002-07-24","article_text":"1. Арбитражный суд по заявлению взыскателя, должника, судебного пристава-исполнителя может приостановить, возобновить или прекратить исполнительное производство, возбужденное Федеральной службой судебных приставов в автоматическом режиме или судебным приставом-исполнителем на основании исполнительного листа, выданного арбитражным судом, в случаях, предусмотренных федеральным законом об исполнительном производстве.\n\nЗаявление о возобновлении приостановленного исполнительного производства может быть подано лицами, указанными в настоящей части, в течение трех лет с момента устранения обстоятельств, послуживших основанием для его приостановления.\n\n2. Пропущенный по уважительной причине срок подачи заявления о возобновлении исполнительного производства может быть восстановлен судом на основании ходатайства взыскателя, должника, судебного пристава-исполнителя. Указанное ходатайство рассматривается в порядке, предусмотренном статьей 117 настоящего Кодекса.\n\n3. Приостановление, возобновление или прекращение исполнительного производства производится арбитражным судом, выдавшим исполнительный лист, либо арбитражным судом по месту нахождения судебного пристава-исполнителя, в том числе ведущего исполнительное производство, решение о возбуждении которого принято Федеральной службой судебных приставов в автоматическом режиме.\n\n4. Заявление о приостановлении, возобновлении или прекращении исполнительного производства рассматривается в десятидневный срок со дня поступления такого заявления в суд в порядке, предусмотренном статьей 324 настоящего Кодекса.\n\n5. Определение арбитражного суда о приостановлении, возобновлении или прекращении исполнительного производства либо об отказе в удовлетворении заявления о приостановлении, возобновлении или прекращении исполнительного производства может быть обжаловано.\n\n(Статья в редакции  Федерального закона от 06.04.2024 № 74-ФЗ)","article_title":"Статья 327. Приостановление, возобновление или прекращение исполнительного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"00416a031f535272b799f344c6152a7f7dd6616befb9737d56f0174fc3782ddd"},{"code_id":"APK_RF","article_number":"328","version_date":"2002-07-24","article_text":"1. При наличии обстоятельств, препятствующих совершению отдельных исполнительных действий, арбитражный суд по заявлению взыскателя, должника или судебного пристава-исполнителя может отложить исполнительные действия по исполнительному производству, возбужденному на основании исполнительного листа, выданного арбитражным судом.\n\n2. Отложение исполнительных действий производится арбитражным судом, выдавшим исполнительн\n\nый лист, или арбитражным судом по месту нахождения судебного пристава-исполнителя.3. Заявление об отложении исполнительных действий рассматривается арбитражным судом в десятидневный срок в порядке, предусмотренном статьей 324 настоящего Кодекса.По результатам рассмотрения заявления суд выносит определение.4. В определении об отложении исполнительных действий указывается дата, до которой откладываются исполнительные действия, или событие, наступление которого является основанием для возобновления судебным приставом-исполнителем исполнительных действий.Копии определения об отложении исполнительных действий направляются взыскателю, должнику и судебному приставу-исполнителю.Статья 329. Оспаривание постановлений должностных лиц службы судебных приставов, их действий (бездействия)1. Постановления главного судебного пристава Российской Федерации, главного судебного пристава субъекта (главного судебного пристава субъектов) Российской Федерации, старшего судебного пристава, их заместителей, судебного пристава-исполнителя, их действия (бездействие) могут быть оспорены в арбитражном суде в случаях, предусмотренных настоящим Кодексом и другими федеральными законами, по правилам, установленным главой 24 настоящего Кодекса. (В редакции Федерального закона от 30.12.2015 № 425-ФЗ)2. Заявление об оспаривании постановлений должностных лиц службы судебных приставов, их действий (бездействия) государственной пошлиной не облагается.(Статья в редакции Федерального закона от 02.10.2007 № 225-ФЗ)Статья 330. Ответственность за неисполнение или ненадлежащее исполнение судебным приставом-исполнителем своих обязанностей1. Вред, причиненный судебным приставом-исполнителем в результате неисполнения или ненадлежащего исполнения своих обязанностей по исполнению исполнительного листа, выданного арбитражным судом, подлежит возмещению в порядке, предусмотренном гражданским законодательством.2. Требование о возмещении вреда рассматривается арбитражным судом по общим правилам искового производства, предусмотренным настоящим Кодексом.Статья 331. Ответственность за утрату исполнительного листаНа лицо, виновное в утрате переданного ему на исполнение исполнительного листа, выданного арбитражным судом, арбитражный суд вправе наложить судебный штраф в порядке и в размере, установленных в главе 11 настоящего Кодекса.Статья 332. Ответственность за неисполнение судебного акта(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)1. За неисполнение судебного акта арбитражного суда органами государственной власти, органами местного самоуправления, иными органами, организациями, должностными лицами и гражданами арбитражным судом может быть наложен судебный штраф по правилам главы 11 настоящего Кодекса в размере, установленном федеральным законом. (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)2. За неисполнение указанных в исполнительном листе действий лицом, на которое возложено совершение этих действий, на это лицо арбитражным судом, выдавшим исполнительный лист, может быть наложен судебный штраф в порядке и в размере, установленных в главе 11 настоящего Кодекса.3. Уплата судебного штрафа не освобождает от обязанности исполнить судебный акт.4. Вопрос о наложении судебного штрафа рассматривается арбитражным судом по заявлению взыскателя или судебного пристава-исполнителя в порядке, установленном настоящим Кодексом.Президент Российской Федерации                              В.ПутинМосква, Кремль24 июля 2002 года№ 95-ФЗ\n\nый лист, или арбитражным судом по месту нахождения судебного пристава-исполнителя.\n\n3. Заявление об отложении исполнительных действий рассматривается арбитражным судом в десятидневный срок в порядке, предусмотренном статьей 324 настоящего Кодекса.\n\nПо результатам рассмотрения заявления суд выносит определение.\n\n4. В определении об отложении исполнительных действий указывается дата, до которой откладываются исполнительные действия, или событие, наступление которого является основанием для возобновления судебным приставом-исполнителем исполнительных действий.\n\nКопии определения об отложении исполнительных действий направляются взыскателю, должнику и судебному приставу-исполнителю.","article_title":"Статья 328. Отложение исполнительных действий","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"33e16b6c35f092c1a687b0aec497c455a6ec17b473af3dcd155005e54f9200a6"},{"code_id":"APK_RF","article_number":"329","version_date":"2002-07-24","article_text":"(Статья в редакции Федерального закона от 02.10.2007 № 225-ФЗ)","article_title":"Статья 329. Оспаривание постановлений должностных лиц службы судебных приставов, их действий (бездействия)","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d7bad72b1538e2cade1fe1222ddc9df2988b260076e433e140df7a08379842fc"},{"code_id":"APK_RF","article_number":"33","version_date":"2002-07-24","article_text":"1) споры, предусмотренные пунктами 1, 3, 6 части 6 статьи 27 настоящего Кодекса;\n\n2) споры, предусмотренные разделом III настоящего Кодекса;\n\n3) споры, предусмотренные главами 27, 271 и 282 настоящего Кодекса;\n\n4) споры, предусмотренные пунктами 1 - 5 части 2 статьи 2251 настоящего Кодекса;\n\n5) споры, возникающие из отношений, регулируемых законодательством Российской Федерации о приватизации государственного и муниципального имущества;\n\n6) споры, возникающие из отношений, регулируемых законодательством Российской Федерации о контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд;\n\n7) споры, возникающие из отношений, связанных с возмещением вреда, причиненного окружающей среде;\n\n8) иные споры в случаях, прямо предусмотренных федеральным законом.\n\n(Статья в редакции Федерального закона от 29.12.2015 № 409-ФЗ)\n\n(Обозначение и наименование параграфа исключены - Федеральный закон от 28.11.2018 № 451-ФЗ)","article_title":"Статья 33. Споры, подлежащие передаче на рассмотрение третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9445060a363d79695a01556fd1368fc518bde9dc62c0f90a04cfe47c85a5edc7"},{"code_id":"APK_RF","article_number":"330","version_date":"2002-07-24","article_text":"1. Вред, причиненный судебным приставом-исполнителем в результате неисполнения или ненадлежащего исполнения своих обязанностей по исполнению исполнительного листа, выданного арбитражным судом, подлежит возмещению в порядке, предусмотренном гражданским законодательством.\n\n2. Требование о возмещении вреда рассматривается арбитражным судом по общим правилам искового производства, предусмотренным настоящим Кодексом.","article_title":"Статья 330. Ответственность за неисполнение или ненадлежащее исполнение судебным приставом-исполнителем своих обязанностей","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"83af1233b1259733c0214c22ebd7891210a1248bbb8d92c2d80365a9dbb944dd"},{"code_id":"APK_RF","article_number":"331","version_date":"2002-07-24","article_text":"На лицо, виновное в утрате переданного ему на исполнение исполнительного листа, выданного арбитражным судом, арбитражный суд вправе наложить судебный штраф в порядке и в размере, установленных в главе 11 настоящего Кодекса.","article_title":"Статья 331. Ответственность за утрату исполнительного листа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9481dc6ecbc7f66c6e3b35307905df2d301c058287f517377f088f36ed8fff4f"},{"code_id":"APK_RF","article_number":"332","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\nПрезидент Российской Федерации                              В.Путин\n\nМосква, Кремль\n\n24 июля 2002 года","article_title":"Статья 332. Ответственность за неисполнение судебного акта","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"82417fc0f70e050e1abc9d1345ddc6e21c71ec6b4a820bcfe9ac5b696badd6e1"},{"code_id":"APK_RF","article_number":"34","version_date":"2002-07-24","article_text":"1) дела об оспаривании нормативных правовых актов федеральных органов исполнительной власти в сфере патентных прав и прав на селекционные достижения, права на топологии интегральных микросхем, права на секреты производства (ноу-хау), права на средства индивидуализации юридических лиц, товаров, работ, услуг и предприятий, права использования результатов интеллектуальной деятельности в составе единой технологии; (В редакции Федерального закона от 28.06.2014 № 186-ФЗ)\n\n11) дела об оспаривании актов федеральных органов исполнительной власти в сфере патентных прав и прав на селекционные достижения, права на топологии интегральных микросхем, права на секреты производства (ноу-хау), права на средства индивидуализации юридических лиц, товаров, работ, услуг и предприятий, права использования результатов интеллектуальной деятельности в составе единой технологии, содержащих разъяснения законодательства и обладающих нормативными свойствами; (Дополнение пунктом - Федеральный закон от 15.02.2016 № 18-ФЗ)\n\n2) дела по спорам о предоставлении или прекращении правовой охраны результатов интеллектуальной деятельности и приравненных к ним средств индивидуализации юридических лиц, товаров, работ, услуг и предприятий (за исключением объектов авторских и смежных прав, топологий интегральных микросхем), в том числе:\n\nоб оспаривании ненормативных правовых актов, решений и действий (бездействия) фе\n\nдерального органа исполнительной власти по интеллектуальной собственности, федерального органа исполнительной власти по селекционным достижениям и их должностных лиц, а также органов, уполномоченных Правительством Российской Федерации рассматривать заявки на выдачу патента на секретные изобретения;\n\nоб оспаривании решений федерального антимонопольного органа о признании недобросовестной конкуренцией действий, связанных с приобретением исключительного права на средства индивидуализации юридического лица, товаров, работ, услуг и предприятий;\n\nоб установлении патентообладателя;\n\nо признании недействительными патента на изобретение, полезную модель, промышленный образец или селекционное достижение, решения о предоставлении правовой охраны товарному знаку, наименованию места происхождения товара и о предоставлении исключительного права на такое наименование, если федеральным законом не предусмотрен иной порядок их признания недействительными;\n\nо досрочном прекращении правовой охраны товарного знака вследствие его неиспользования.\n\n(Дополнение частью - Федеральный закон от 08.12.2011 № 422-ФЗ)","article_title":"Статья 34. Подсудность дел арбитражным судам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"caacd619d7165335d3aed56fea6fc8b76e630261f46715d4c9d8a0319b4b899f"},{"code_id":"APK_RF","article_number":"35","version_date":"2002-07-24","article_text":"Иск предъявляется в арбитражный суд субъекта Российской Федерации по адресу или месту жительства ответчика.\n\n(Статья в редакции Федерального закона от 28.11.2018 № 451-ФЗ)","article_title":"Статья 35. Предъявление иска по адресу или месту жительства ответчика","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"13148b7bc560bedf116f207f8bfa3e1a241c099a903b642576dcbdaee8f4855c"},{"code_id":"APK_RF","article_number":"36","version_date":"2002-07-24","article_text":"1. Иск к ответчику, место нахождения или место жительства которого неизвестно, может быть предъявлен в арбитражный суд по месту нахождения его имущества либо по его последнему известному месту нахождения или месту жительства в Российской Федерации.","article_title":"Статья 36. Подсудность по выбору истца","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"919397595530c13ea20ea647189974b9aeed7c81c0a00b87a2f4cff2b7325369"},{"code_id":"APK_RF","article_number":"37","version_date":"2002-07-24","article_text":"Подсудность, установленная статьями 35 и 36 настоящего Кодекса, может быть изменена по соглашению сторон до принятия арбитражным судом заявления к своему производству.","article_title":"Статья 37. Договорная подсудность","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3c69d60d508a7aae212bac1190883c2c7725ceb8b926caafffcce7dea8d459cf"},{"code_id":"APK_RF","article_number":"38","version_date":"2002-07-24","article_text":"1. Иски о правах на недвижимое имущество предъявляются в арбитражный суд по месту нахождения этого имущества.\n\n2. Иски о правах на морские и воздушные суда, суда внутреннего плавания, космические объекты предъявляются в арбитражный суд по месту их государственной регистрации.\n\n3. Иск к перевозчику, вытекающий из договора перевозки грузов, пассажиров и их багажа, в том числе в случае, если перевозчик является одним из ответчиков, предъявляется в арбитражный суд по месту нахождения перевозчика.\n\nЗаявление об оспаривании решения Федеральной службы судебных приставов, принятого в автоматическом режиме, подается в арбитражный суд по месту совершения исполнительных действий или применения мер принудительного исполнения либо по месту ведения исполнительного производства, по которому принято оспариваемое решение. (Дополнение абзацем - Федеральный закон от 21.12.2021 № 417-ФЗ)\n\nЗаявления по спорам между российскими организациями, осуществляющими деятельность или имеющими имущество на территории иностранного государства и не имеющими государственной регистрации на территории Российской Федерации, подаются в Арбитражный суд Московской области.","article_title":"Статья 38. Исключительная подсудность","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4898d097a6464cccdc4ee6ead6a1bac9aa1c64a76acb276ffc0f864e7c76789f"},{"code_id":"APK_RF","article_number":"39","version_date":"2002-07-24","article_text":"1. Дело, принятое арбитражным судом к своему производству с соблюдением правил подсудности, должно быть рассмотрено им по существу, хотя бы в дальнейшем оно стало подсудным другому суду.\n\n2. Арбитражный суд передает дело на рассмотрение другого арбитражного суда того же уровня в случае, если:\n\n1) ответчик, адрес или место жительства которого не было известно ранее, заявит ходатайство о передаче дела в арбитражный суд по его адресу или месту жительства;\n\n2) обе стороны заявили ходатайство о рассмотрении дела по месту нахождения большинства доказательств;\n\n3) при рассмотрении дела в суде выяснилось, что оно было принято к производству с нарушением правил подсудности;\n\n4) при рассмотрении дела в суде было установлено, что лицом, участвующим в деле, является тот же арбитражный суд;\n\n5) после отвода одного или нескольких судей либо по другим причинам невозможно сформировать состав суда для рассмотрения данного дела.\n\n3. В предусмотренном пунктом 4 части 2 настоящей статьи случае арбитражный суд передает дело на рассмотрение другого определяемого в соответствии с частью 31 статьи 38 настоящего Кодекса арбитражного суда.\n\n4. Если при рассмотрении дела в арбитражном суде выяснилось, что оно подлежит рассмотрению судом общей юрисдикции, арбитражный суд передает дело в верховный суд республики, краевой, областной суд, суд города федерального значения, суд автономной области или суд автономного округа того же субъекта Российской Федерации для направления его в суд общей юрисдикции, к подсудности которого оно отнесено законом.\n\n5. По результатам рассмотрения арбитражным судом вопроса о передаче дела на рассмотрение другого арбитражного суда или суда общей юрисдикции выносится определение, которое может быть обжаловано в арбитражный суд апелляционной инстанции в десятидневный срок со дня его вынесения. Жалоба на это определение рассматривается без вызова сторон в пятидневный срок со дня ее поступления в суд. Дело и определение направляются в арбитражный суд или суд общей юрисдикции по истечении срока, предусмотренного для обжалования этого определения, а в случае подачи жалобы - после принятия постановления суда об оставлении жалобы без удовлетворения.\n\n6. Дело, направленное из одного арбитражного суда в другой арбитражный суд или из арбитражного суда в суд общей юрисдикции, должно быть принято к рассмотрению судом, в который оно направлено. Споры о подсудности между судами в Российской Федерации не допускаются.\n\n(Статья в редакции Федерального закона от 28.11.2018 № 451-ФЗ)","article_title":"Статья 39. Передача дела, принятого арбитражным судом к своему производству, из одного суда в другой суд","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f99f62f7f96a2e4d4d47eeb3d9b002d900d3fa51a7182274c3444086c8b90351"},{"code_id":"APK_RF","article_number":"4","version_date":"2002-07-24","article_text":"искового заявления - по экономическим спорам и иным делам, возникающим из гражданских правоотношений;\n\nзаявления - по делам, возникающим из административных и иных публичных правоотношений, по делам о несостоятельности (банкротстве), по делам особого производства, по делам приказного производства и в иных случаях, предусмотренных настоящим Кодексом; (В редакции федеральных законов от 28.06.2014 № 186-ФЗ; от 02.03.2016 № 47-ФЗ)\n\nжалобы - при обращении в арбитражный суд апелляционной и кассационной инстанций, а также в иных случаях, предусмотренных настоящим Кодексом и иными федеральными законами;\n\nпредставления - при обращении Генерального прокурора Российской Федерации и его заместителей о пересмотре судебных актов в порядке надзора.\n\nИные споры, возникающие из гражданских правоотношений, передаются на разрешение арбитражного суда после соблюдения досудебного порядка урегулирования спора только в том случае, если такой порядок установлен федеральным законом или договором.\n\nЭкономические споры, возникающие из административных и иных публичных правоотношений, могут быть переданы на разрешение арбитражного суда после соблюдения досудебного порядка урегулирования спора в случае, если такой порядок установлен федеральным законом.\n\nСоблюдения досудебного порядка урегулирования спора не требуется по делам об установлении фактов, имеющих юридическое значение, делам о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок, делам о несостоятельности (банкротстве), делам по корпоративным спорам, делам о защите прав и законных интересов группы лиц, делам приказного производства, делам, связанным с выполнением арбитражными судами функций содействия и контроля в отношении третейских судов, делам о признании и приведении в исполнение решений иностранных судов и иностранных арбитражных решений, а также, если иное не предусмотрено законом, при обращении в арбитражный суд прокурора, государственных органов, органов местного самоуправления и иных органов в защиту публичных интересов, прав и законных интересов организаций и граждан в сфере предпринимательской и иной экономической деятельности (статьи 52, 53 настоящего Кодекса).\n\n(Часть в редакции Федерального закона от 01.07.2017 № 147-ФЗ)\n\nИсковое заявление, заявление, жалоба, представление и иные документы в электронном виде могут быть поданы в суд посредством федеральной государственной информационной системы \"Единый портал государственных и муниципальных услуг (функций)\" (далее - единый портал государственных и муниципальных услуг), либо информационной системы, определенной Верховным Судом Российской Федерации, Судебным департаментом при Верховном Суде Российской Федерации, либо систем электронного документооборота участников арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия.\n\nИсковое заявление, заявление, жалоба, представление и иные документы, которые подаются посредством единого портала государственных и муниципальных услуг, информационной системы, определенной Верховным Судом Российской Федерации, Судебным департаментом при Верховном Суде Российской Федерации, могут быть подписаны простой электронной подписью в соответствии с законодательством Российской Федерации и порядком, определяемым Верховным Судом Российской Федерации, Судебным департаментом при Верховном Суде Российской Федерации, если настоящим Кодексом не установлено, что указанные документы должны быть подписаны усиленной квалифицированной электронной подписью.\n\nИсковое заявление, заявление, жалоба, представление и иные документы, которые подаются посредством систем электронного документооборота участников арбитражного процесса, должны быть подписаны усиленной квалифицированной электронной подписью.\n\n(Дополнение частью - Федеральный закон от 23.06.2016 № 220-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)","article_title":"Статья 4. Право на обращение в арбитражный суд","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a65021ab06b57d00c571192fea38670f20c8e2cf3e24a42ba5bd4a9914e8f581"},{"code_id":"APK_RF","article_number":"40","version_date":"2002-07-24","article_text":"Лицами, участвующими в деле, являются:\n\nзаявители и заинтересованные лица - по делам особого производства, по делам о несостоятельности (банкротстве) и в иных предусмотренных настоящим Кодексом случаях;\n\nтретьи лица;\n\nпрокурор, государственные органы, органы местного самоуправления, иные органы и организации, граждане, обратившиеся в арбитражный суд в случаях, предусмотренных настоящим Кодексом. (В редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 40. Состав лиц, участвующих в деле","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"64fa30b5b1e6feb7c02389549ee5b13bac9c6641946c1838e167fe0e571cdc7f"},{"code_id":"APK_RF","article_number":"41","version_date":"2002-07-24","article_text":"Лица, участвующие в деле, также вправе представлять в арбитражный суд документы в электронном виде, в том числе в форме электронного документа, подписанного электронной подписью в порядке, установленном законодательством Российской Федерации. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 228-ФЗ) (В редакции федеральных законов от 23.06.2016 № 220-ФЗ, от 30.12.2021 № 440-ФЗ)\n\nЗлоупотребление процессуальными правами лицами, участвующими в деле, влечет за собой для этих лиц предусмотренные настоящим Кодексом неблагоприятные последствия.\n\nНеисполнение процессуальных обязанностей лицами, участвующими в деле, влечет за собой для этих лиц предусмотренные настоящим Кодексом последствия.","article_title":"Статья 41. Права и обязанности лиц, участвующих в деле","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"49bd89eb81b9a082322635f49f9a59dc2acb4a27c3771b34063a17e4022e3585"},{"code_id":"APK_RF","article_number":"42","version_date":"2002-07-24","article_text":"Лица, не участвовавшие в деле, о правах и об обязанностях которых арбитражный суд принял судебный акт, вправе обжаловать этот судебный акт, а также оспорить его в порядке надзора по правилам, установленным настоящим Кодексом. Такие лица пользуются правами и несут обязанности лиц, участвующих в деле.","article_title":"Статья 42. Права лиц, не участвовавших в деле, о правах и об обязанностях которых арбитражный суд принял судебный акт","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e81b7fb5243fed62fd7371f8e6177d5e7d14f13d94b5aaaf138671a04e0cc448"},{"code_id":"APK_RF","article_number":"43","version_date":"2002-07-24","article_text":"1. Способность иметь процессуальные права и нести процессуальные обязанности (процессуальная правоспособность) признается в равной мере за всеми организациями и гражданами, обладающими согласно федеральному закону правом на судебную защиту в арбитражном суде своих прав и законных интересов.\n\n2. Способность своими действиями осуществлять процессуальные права и исполнять процессуальные обязанности (процессуальная дееспособность) принадлежит в арбитражном суде организациям и гражданам.\n\n3. Права и законные интересы недееспособных граждан защищают в арбитражном процессе их законные представители - родители, усыновители, опекуны или попечители.","article_title":"Статья 43. Процессуальная правоспособность и процессуальная дееспособность","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a1f8241cf1e96cced45d7d3fc28a7fbf594c6c35df1b54492078b99d4fb9d767"},{"code_id":"APK_RF","article_number":"44","version_date":"2002-07-24","article_text":"1. Сторонами в арбитражном процессе являются истец и ответчик.\n\n2. Истцами являются организации и граждане, предъявившие иск в защиту своих прав и законных интересов.\n\n3. Ответчиками являются организации и граждане, к которым предъявлен иск.\n\n4. Стороны пользуются равными процессуальными правами.","article_title":"Статья 44. Стороны","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1d274f05d4e56aba73b1a30e128cfbe26c36f63f49c11da04039ed3195cd42b1"},{"code_id":"APK_RF","article_number":"45","version_date":"2002-07-24","article_text":"1. Заявителями являются организации и граждане, обращающиеся в арбитражный суд с заявлениями в предусмотренных настоящим Кодексом и иным федеральным законом случаях и вступающие в арбитражный процесс по этим заявлениям.\n\n2. Заявители пользуются процессуальными правами и несут процессуальные обязанности стороны, если иное не предусмотрено настоящим Кодексом.","article_title":"Статья 45. Заявители","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3a80d08ed24943cd2f807c8b46252f44e840e03e12757a8db9b3476d5adb9f95"},{"code_id":"APK_RF","article_number":"46","version_date":"2002-07-24","article_text":"1. Иск может быть предъявлен в арбитражный суд совместно несколькими истцами или к нескольким ответчикам (процессуальное соучастие).\n\n2. Процессуальное соучастие допускается, если:\n\n1) предметом спора являются общие права и (или) обязанности нескольких истцов либо ответчиков;\n\n2) права и (или) обязанности нескольких истцов либо ответчиков имеют одно основание;\n\n3) предметом спора являются однородные права и обязанности.\n\n3. Каждый из истцов или ответчиков по отношению к другой стороне выступает в процессе самостоятельно. Соучастники могут поручить ведение дела одному или нескольким из них.\n\n4. Соистцы могут вступить в дело до принятия судебного акта, которым заканчивается рассмотрение дела по существу в арбитражном суде первой инстанции.\n\n5. При невозможности рассмотрения дела без участия другого лица в качестве ответчика арбитражный суд первой инстанции привлекает его к участию в деле как соответчика по ходатайству сторон или с согласия истца.\n\n6. В случае, если федеральным законом предусмотрено обязательное участие в деле другого лица в качестве ответчика, а также по делам, вытекающим из административных и иных публичных правоотношений, арбитражный суд первой инстанции по своей инициативе привлекает его к участию в деле в качестве соответчика.\n\n7. О вступлении в дело соистца, о привлечении соответчика или об отказе в этом выносится определение. Определение об отказе в удовлетворении ходатайства о вступлении в дело соистца, о привлечении соответчика может быть обжаловано лицом, подавшим соответствующее ходатайство, в срок, не превышающий десяти дней со дня его вынесения, в арбитражный суд апелляционной инстанции.\n\n8. После вступления в дело соистца, привлечения к участию в деле соответчика рассмотрение дела производится с самого начала.\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 46. Участие в деле нескольких истцов или ответчиков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5b822d5fb1478783a29a3f21088a637ac98700bbaefb88a60339096eecdd6092"},{"code_id":"APK_RF","article_number":"47","version_date":"2002-07-24","article_text":"1. В случае, если при подготовке дела к судебному разбирательству или во время судебного разбирательства в суде первой инстанции будет установлено, что иск предъявлен не к тому лицу, которое должно отвечать по иску, арбитражный суд может по ходатайству или с согласия истца допустить замену ненадлежащего ответчика надлежащим.\n\n2. Если истец не согласен на замену ответчика другим лицом, суд может с согласия истца привлечь это лицо в качестве второго ответчика.\n\n3. После замены ненадлежащего ответчика или вступления в дело второго ответчика рассмотрение дела производится с самого начала.\n\n4. О замене ненадлежащего ответчика надлежащим или привлечении надлежащего ответчика в качестве второго ответчика арбитражный суд выносит определение.\n\nЕсли истец не согласен на замену ответчика другим лицом или на привлечение этого лица в качестве второго ответчика, арбитражный суд рассматривает дело по предъявленному иску.","article_title":"Статья 47. Замена ненадлежащего ответчика","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1575a0aae753755e5bfe20e719dd59b30378abe56baae744a2ac8b4ac8e5c897"},{"code_id":"APK_RF","article_number":"48","version_date":"2002-07-24","article_text":"1. В случаях выбытия одной из сторон в спорном или установленном судебным актом арбитражного суда правоотношении (реорганизация юридического лица, уступка требования, перевод долга, смерть гражданина и другие случаи перемены лиц в обязательствах) арбитражный суд производит замену этой стороны ее правопреемником и указывает на это в судебном акте. Правопреемство возможно на любой стадии арбитражного процесса.","article_title":"Статья 48. Процессуальное правопреемство","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"438381279db3d48d55b103b5fddad7c878f6039d2298199a7974d1d6caf94dac"},{"code_id":"APK_RF","article_number":"49","version_date":"2002-07-24","article_text":"1. Истец вправе при рассмотрении дела в арбитражном суде первой инстанции до принятия судебного акта, которым заканчивается рассмотрение дела по существу, изменить основание или предмет иска, увеличить или уменьшить размер исковых требований.","article_title":"Статья 49. Изменение основания или предмета иска, изменение размера исковых требований, отказ от иска, признание иска, мировое соглашение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0f16466a27f0e600a06ab91aebda3fcd7a628b070a2347fcaef718e17eb4b4a6"},{"code_id":"APK_RF","article_number":"5","version_date":"2002-07-24","article_text":"1. При осуществлении правосудия судьи арбитражных судов независимы, подчиняются только Конституции Российской Федерации и федеральному закону.\n\n2. Какое-либо постороннее воздействие на судей арбитражных судов, вмешательство в их деятельность государственных органов, органов местного самоуправления, иных органов, организаций, должностных лиц или граждан запрещаются и влекут за собой ответственность, установленную законом.\n\n3. Гарантии независимости судей арбитражных судов устанавливаются Конституцией Российской Федерации и федеральным законом.","article_title":"Статья 5. Независимость судей арбитражных судов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6b8e1d9d6c8655107493894fdcb95636908513b9c1165103382b8e0441ad2708"},{"code_id":"APK_RF","article_number":"50","version_date":"2002-07-24","article_text":"1. Третьи лица, заявляющие самостоятельные требования относительно предмета спора, могут вступить в дело до принятия решения арбитражным судом первой инстанции.\n\n2. Третьи лица, заявляющие самостоятельные требования относительно предмета спора, пользуются правами и несут обязанности истца, за исключением обязанности соблюдения претензионного или иного досудебного порядка урегулирования спора, если это предусмотрено федеральным законом для данной категории споров или договором.\n\n3. В случае, если третье лицо, заявляющее самостоятельные требования относительно предмета спора, вступило в дело после начала судебного разбирательства, рассмотрение дела в первой инстанции арбитражного суда производится с самого начала.","article_title":"Статья 50. Третьи лица, заявляющие самостоятельные требования относительно предмета спора","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c40715c1fa7aea7cece80e992bed018f4ee82204088c0d4c2b15c933e955f030"},{"code_id":"APK_RF","article_number":"51","version_date":"2002-07-24","article_text":"1. Третьи лица, не заявляющие самостоятельных требований относительно предмета спора, могут вступить в дело на стороне истца или ответчика до принятия судебного акта, которым заканчивается рассмотрение дела в первой инстанции арбитражного суда, если этот судебный акт может повлиять на их права или обязанности по отношению к одной из сторон. Они могут быть привлечены к участию в деле также по ходатайству стороны или по инициативе суда.","article_title":"Статья 51. Третьи лица, не заявляющие самостоятельных требований относительно предмета спора","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"925822071b7f197dc86659839fe366d965b32e310ecc887dc6ba8f76cf7841d6"},{"code_id":"APK_RF","article_number":"52","version_date":"2002-07-24","article_text":"1. Прокурор вправе обратиться в арбитражный суд:\n\nс заявлениями об оспаривании нормативных правовых актов, ненормативных правовых актов органов государственной власти Российской Федерации, органов государственной власти субъектов Российской Федерации, органов местного самоуправления, затрагивающих права и законные интересы организаций и граждан в сфере предпринимательской и иной экономической деятельности;\n\nс иском о признании недействительными сделок, совершенных органами государственной власти Российской Федерации, органами государственной власти субъектов Российской Федерации, органами местного самоуправления, государственными и муниципальными унитарными предприятиями, государственными учреждениями, а также юридическими лицами, в уставном капитале (фонде) которых есть доля участия Российской Федерации, доля участия субъектов Российской Федерации, доля участия муниципальных образований;\n\nс иском о применении последствий недействительности ничтожной сделки, совершенной органами государственной власти Российской Федерации, органами государственной власти субъектов Российской Федерации, органами местного самоуправления, государственными и муниципальными унитарными предприятиями, государственными учреждениями, а также юридическими лицами, в уставном капитале (фонде) которых есть доля участия Российской Федерации, доля участия субъектов Российской Федерации, доля участия муниципальных образований;\n\nс иском об истребовании государственного и муниципального имущества из чужого незаконного владения; (Дополнение абзацем - Федеральный закон от 28.06.2014 № 186-ФЗ)\n\nс иском о признании недействительными сделок, совершенных с нарушением требований законодательства в сфере государственного оборонного заказа в том числе государственными заказчиками государственного оборонного заказа, головными исполнителями поставок продукции по государственному оборонному заказу и исполнителями, участвующими в поставках продукции по государственному оборонному заказу, не указанными в абзацах третьем и четвертом настоящей части, и о применении последствий недействительности таких сделок; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 282-ФЗ)\n\nс иском о признании недействительными сделок, совершенных с нарушением требований законодательства о контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд в том числе заказчиками, поставщиками (подрядчиками, исполнителями), субподрядчиками, соисполнителями, участвующими в обеспечении государственных и муниципальных нужд, не указанными в абзацах третьем и четвертом настоящей части, и о применении последствий недействительности таких сделок; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 282-ФЗ)\n\nс иском о возмещении ущерба, причиненного Российской Федерации, субъектам Российской Федерации и муниципальным образованиям в результате нарушения законодательства в сфере государственного оборонного заказа, а также законодательства о контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 282-ФЗ)\n\nс иском о признании недействительными сделок, совершенных в целях уклонения от исполнения обязанностей и процедур, предусмотренных законодательством о противодействии легализации (отмыванию) доходов, полученных преступным путем, и финансированию терроризма, законодательством о налогах и сборах, валютным законодательством Российской Федерации, правом Евразийского экономического союза в сфере таможенных правоотношений и законодательством Российской Федерации о таможенном регулировании, и о применении последствий недействительности таких сделок; (Дополнение абзацем - Федеральный закон от 07.10.2022 № 387-ФЗ)\n\nс иском о признании недействительными сделок, совершенных с нарушением законодательства, устанавливающего специальные экономические меры, меры воздействия (противодействия) на недружественные действия иностранных государств, и о применении последствий недействительности таких сделок. (Дополнение абзацем - Федеральный закон от 07.10.2022 № 387-ФЗ)\n\nпо категориям дел, указанным в части 1 настоящей статьи;\n\nпри рассмотрении заявлений о выдаче исполнительного листа на принудительное исполнение решения третейского суда;\n\nпри рассмотрении заявлений о признании и приведении в исполнение решений иностранных судов и иностранных арбитражных решений;\n\nв случае выявления обстоятельств, свидетельствующих о том, что являющийся предметом судебного разбирательства спор инициирован в целях уклонения от исполнения обязанностей и процедур, предусмотренных законодательством о противодействии легализации (отмыванию) доходов, полученных преступным путем, и финансированию терроризма, законодательством о налогах и сборах, валютным законодательством Российской Федерации, правом Евразийского экономического союза в сфере таможенных правоотношений и законодательством Российской Федерации о таможенном регулировании, а также законодательством, устанавливающим специальные экономические меры, меры воздействия (противодействия) на недружественные действия иностранных государств, и (или) возник из мнимой или притворной сделки, совершенной в указанных целях;\n\nв случае, если в рамках дела о несостоятельности (банкротстве) затрагиваются жилищные права граждан, в том числе несовершеннолетних.\n\n(Часть в редакции Федерального закона от 07.10.2022 № 387-ФЗ)","article_title":"Статья 52. Участие в деле прокурора","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b3d8d8b38c6a10e73e85254af8e788b150964aba51ef20026f6ecbe6f39b9f8"},{"code_id":"APK_RF","article_number":"53","version_date":"2002-07-24","article_text":"1. В случаях, предусмотренных федеральным законом, государственные органы, органы местного самоуправления и иные органы вправе обратиться в арбитражный суд в защиту публичных интересов.\n\n2. В случаях, предусмотренных настоящим Кодексом и другими федеральными законами, организации и граждане вправе обратиться в арбитражный суд в защиту прав и законных интересов других лиц.\n\n3. В обращении должно быть указано, в чем заключается нарушение публичных интересов или прав и (или) законных интересов других лиц, послужившее основанием для обращения в арбитражный суд.\n\n4. Орган, обратившийся в арбитражный суд в защиту публичных интересов, организации и граждане, обратившиеся в защиту прав и законных интересов других лиц, пользуются процессуальными правами и несут процессуальные обязанности истца.\n\n5. Отказ органов, организаций и граждан, указанных в частях 1 и 2 настоящей статьи, от предъявленного иска не лишает истца права требовать рассмотрения дела по существу.\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 53. Обращение в защиту публичных интересов, прав и законных интересов других лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"487b84c068e92fff623ea9a5d9d09d004fb74bb386d7fcf2027da0b8b544976c"},{"code_id":"APK_RF","article_number":"53.1","version_date":"2002-07-24","article_text":"1. Уполномоченный при Президенте Российской Федерации по защите прав предпринимателей, уполномоченные по защите прав предпринимателей в субъектах Российской Федерации, обратившиеся в арбитражный суд, пользуются процессуальными правами и несут процессуальные обязанности истца.\n\n2. Уполномоченный при Президенте Российской Федерации по защите прав предпринимателей вправе вступить в дело на стороне истца или ответчика в качестве третьего лица, не заявляющего самостоятельных требований.\n\n3. Уполномоченный при Президенте Российской Федерации по защите прав предпринимателей вправе обжаловать вступившие в законную силу судебные акты по правилам, установленным статьей 42 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 02.11.2013 № 294-ФЗ)","article_title":"Статья 53.1. Участие в деле Уполномоченного при Президенте Российской Федерации по защите прав предпринимателей, уполномоченных по защите прав предпринимателей в субъектах Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1527afaceb5718bbdb9b62b866f3c8c900239ae25624e071f6b10f5af353bf9b"},{"code_id":"APK_RF","article_number":"54","version_date":"2002-07-24","article_text":"В арбитражном процессе наряду с лицами, участвующими в деле, могут участвовать их представители и содействующие осуществлению правосудия лица - эксперты, специалисты, свидетели, переводчики, помощник судьи и секретарь судебного заседания. (В редакции Федерального закона от 08.12.2011 № 422-ФЗ)","article_title":"Статья 54. Иные участники арбитражного процесса","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bd0e131cca18c075291b9f62b8c5243508f6d76165d4de562296c99fc060d87e"},{"code_id":"APK_RF","article_number":"55","version_date":"2002-07-24","article_text":"1. Экспертом в арбитражном суде является лицо, обладающее специальными знаниями по касающимся рассматриваемого дела вопросам и назначенное судом для дачи заключения в случаях и в порядке, которые предусмотрены настоящим Кодексом.\n\n2. Лицо, которому поручено проведение экспертизы, обязано по вызову арбитражного суда явиться в суд и дать объективное заключение по поставленным вопросам.\n\n3. Эксперт вправе с разрешения арбитражного суда знакомиться с материалами дела, участвовать в судебных заседаниях, задавать вопросы лицам, участвующим в деле, и свидетелям, заявлять ходатайство о представлении ему дополнительных материалов.\n\n4. Эксперт вправе отказаться от дачи заключения по вопросам, выходящим за пределы его специальных знаний, а также в случае, если представленные ему материалы недостаточны для дачи заключения.\n\n5. За дачу заведомо ложного заключения эксперт несет уголовную ответственность, о чем он предупреждается арбитражным судом и дает подписку.","article_title":"Статья 55. Эксперт","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5074f28ff3d1993c3e2afef80a946c7fe465c2f288530471e1d33f440e694c4c"},{"code_id":"APK_RF","article_number":"55.1","version_date":"2002-07-24","article_text":"1. Специалистом в арбитражном суде является лицо, обладающее необходимыми знаниями по соответствующей специальности, осуществляющее консультации по касающимся рассматриваемого дела вопросам.\n\n2. Лицо, вызванное арбитражным судом в качестве специалиста, обязано явиться в суд, отвечать на поставленные вопросы, давать в устной форме консультации и пояснения.\n\n3. Специалист вправе с разрешения арбитражного суда знакомиться с материалами дела, участвовать в судебных заседаниях, заявлять ходатайство о представлении ему дополнительных материалов.\n\n4. Специалист вправе отказаться от дачи консультаций по вопросам, выходящим за пределы его специальных знаний, а также в случае, если представленные ему материалы недостаточны для дачи консультации.\n\n(Дополнение статьей - Федеральный закон от 08.12.2011 № 422-ФЗ)","article_title":"Статья 55.1. Специалист","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0b204eb572792129857c8af4ddaaf3e4e1fe7fa02027704578b0917aa23e947e"},{"code_id":"APK_RF","article_number":"56","version_date":"2002-07-24","article_text":"1. Свидетелем является лицо, располагающее сведениями о фактических обстоятельствах, имеющих значение для рассмотрения дела.\n\n2. Свидетель обязан по вызову арбитражного суда явиться в суд.\n\n3. Свидетель обязан сообщить арбитражному суду сведения по существу рассматриваемого дела, которые известны ему лично, и ответить на дополнительные вопросы арбитражного суда и лиц, участвующих в деле.\n\n4. За дачу заведомо ложных показаний, а также за отказ от дачи показаний свидетель несет уголовную ответственность, о чем он предупреждается арбитражным судом и дает подписку.\n\n5. Не подлежат допросу в качестве свидетелей судьи и иные лица, участвующие в осуществлении правосудия, об обстоятельствах, которые стали им известны в связи с участием в рассмотрении дела, представители по гражданскому и иному делу - об обстоятельствах, которые стали им известны в связи с исполнением обязанностей представителей, а также лица, которые в силу психических недостатков не способны правильно понимать факты и давать о них показания.\n\n6. Никто не обязан свидетельствовать против себя самого, своего супруга и близких родственников, круг которых определяется федеральным законом.\n\n7. Свидетель имеет право на возмещение расходов, связа\n\nнных с вызовом в суд, и получение денежной компенсации в связи с потерей времени.","article_title":"Статья 56. Свидетель","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"573d42ddaf73c470c86fb7aaa79ad2df31376d44b037e6879a2d0fc6a5c17b97"},{"code_id":"APK_RF","article_number":"57","version_date":"2002-07-24","article_text":"1. Переводчиком является лицо, которое свободно владеет языком, знание которого необходимо для перевода в процессе осуществления судопроизводства, и привлечено арбитражным судом к участию в арбитражном процессе в случаях и в порядке, которые предусмотрены настоящим Кодексом.\n\n2. Лица, участвующие в деле, вправе предложить арбитражному суду кандидатуры переводчика.\n\nИные участники арбитражного процесса не вправе принимать на себя обязанности переводчика, хотя бы они и владели необходимыми для перевода языками.\n\n3. О привлечении переводчика к участию в арбитражном процессе арбитражный суд выносит определение.\n\n4. Переводчик обязан по вызову арбитражного суда явиться в суд и полно, правильно, своевременно осуществлять перевод.\n\n5. Переводчик вправе задавать присутствующим при переводе лицам вопросы для уточнения перевода, знакомиться с протоколом судебного заседания или отдельного процессуального действия и делать замечания по поводу правильности записи перевода.\n\n6. За заведомо неправильный перевод переводчик несет уголовную ответственность, о чем он предупреждается арбитражным судом и дает подписку.\n\n7. Правила настоящей статьи распространяются на лицо, владеющее навыками сурдоперевода и привлеченное арбитражным судом к участию в арбитражном процессе.","article_title":"Статья 57. Переводчик","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c2735ea7a656cf8d3dfb74fa0a0d06e9e202147041b9d32c25f1bcc639eb385c"},{"code_id":"APK_RF","article_number":"59","version_date":"2002-07-24","article_text":"1. Граждане вправе вести свои дела в арбитражном суде лично или через представителей. Ведение дела лично не лишает гражданина права иметь представителей.\n\n2. Права и законные интересы недееспособных граждан защищают в арбитражном процессе их законные представители - родители, усыновители, опекуны или попечители, которые могут поручить ведение дела в арбитражном суде другому избранному ими представителю.\n\nОт имени ликвидируемой организации в суде выступает уполномоченный представитель ликвидационной комиссии.","article_title":"Статья 59. Ведение дел в арбитражном суде через представителей","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bed8153bea34088592b6d7a22381e64c2b7a7326bd32da79dbc63f79a16162f0"},{"code_id":"APK_RF","article_number":"6","version_date":"2002-07-24","article_text":"Законность при рассмотрении дел арбитражным судом обеспечивается правильным применением законов и иных нормативных правовых актов, а также соблюдением всеми судьями арбитражных судов правил, установленных законодательством о судопроизводстве в арбитражных судах.","article_title":"Статья 6. Законность при рассмотрении дел арбитражным судом","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"faae37281ec0a1fedbaeb1a7d7ba9343953844367552302f42c02e7e41fbfc18"},{"code_id":"APK_RF","article_number":"6.1","version_date":"2002-07-24","article_text":"1. Судопроизводство в арбитражных судах и исполнение судебного акта осуществляются в разумные сроки.\n\n2. Разбирательство дел в арбитражных судах осуществляется в сроки, установленные настоящим Кодексом. Продление этих сроков допустимо в случаях и в порядке, которые установлены настоящим Кодексом. В любом случае судопроизводство в арбитражных судах должно осуществляться в разумный срок.\n\n3. При определении разумного срока судопроизводства в арбитражных судах, который включает в себя период со дня поступления искового заявления или заявления в арбитражный суд первой инстанции до дня принятия последнего судебного акта по делу, учитываются такие обстоятельства, как правовая и фактическая сложность дела, поведение участников арбитражного процесса, достаточность и эффективность действий суда, осуществляемых в целях своевременного рассмотрения дела, а также общая продолжительность судебного разбирательства.\n\n(Дополнение статьей - Федеральный закон от 30.04.2010 № 69-ФЗ)","article_title":"Статья 6.1. Разумные сроки судопроизводства в арбитражных судах и исполнения судебного акта","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4b649eb193b360c2e248b5f969595e5ebc40b12514294afc3894fb825c15d9e7"},{"code_id":"APK_RF","article_number":"62","version_date":"2002-07-24","article_text":"1. Представитель вправе совершать от имени представляемого им лица все процессуальные действия, за исключением действий, указанных в части 2 настоящей статьи, если иное не предусмотрено в доверенности или ином документе.","article_title":"Статья 62. Полномочия представителя","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d95ec5a9bcc0efbe0bb5615b220b2adf6f2e1a878629540d707fb766cc582747"},{"code_id":"APK_RF","article_number":"63","version_date":"2002-07-24","article_text":"1. Арбитражный суд обязан проверить полномочия лиц, участвующих в деле, и их представителей.\n\n2. Арбитражный суд решает вопрос о признании полномочий лиц, участвующих в деле, и их представителей и допуске их к участию в судебном заседании на основании исследования документов, предъявленных указанными лицами суду.\n\n3. Документы, подтверждающие полномочия указанных лиц, при необходимости приобщаются к делу, или сведения о них заносятся в протокол судебного заседания.\n\n4. В случае непредставления лицом, участвующим в деле, его представителем необходимых документов в подтверждение полномочий или представления документов, не соответствующих требованиям, установленным настоящим Кодексом и другими федеральными законами, а также в случае нарушения правил о представительстве, установленных статьями 59 и 60 настоящего Кодекса, арбитражный суд отказывает в признании полномочий соответствующего лица на участие в деле, на что указывается в протоколе судебного заседания.","article_title":"Статья 63. Проверка полномочий лиц, участвующих в деле, и их представителей","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e0638a5b3ca5520d754df5ca87cbfe59c0f164223806f19530c4b079c2eb7c48"},{"code_id":"APK_RF","article_number":"64","version_date":"2002-07-24","article_text":"1. Доказательствами по делу являются полученные в предусмотренном настоящим Кодексом и другими федеральными законами порядке сведения о фактах, на основании которых арбитражный суд устанавливает наличие или отсутствие обстоятельств, обосновывающих требования и возражения лиц, участвующих в деле, а также иные обстоятельства, имеющие значение для правильного рассмотрения дела.\n\nВ качестве доказательств допускаются объяснения лиц, участвующих в деле, и иных участников арбитражного процесса, полученные путем использования систем видеоконференц-связи либо системы веб-конференции. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 228-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)","article_title":"Статья 64. Доказательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2b66eec50b53701033ff221e98473bf98bdcd900f70c312174ca9cd39a7fa998"},{"code_id":"APK_RF","article_number":"65","version_date":"2002-07-24","article_text":"1. Каждое лицо, участвующее в деле, должно доказать обстоятельства, на которые оно ссылается как на основание своих требований и возражений. Обязанность доказывания обстоятельств, послуживших основанием для принятия государственными органами, органами местного самоуправления, иными органами, должностными лицами оспариваемых актов, решений, совершения действий (бездействия), возлагается на соответствующие орган или должностное лицо.\n\n2. Обстоятельства, имеющие значение для правильного рассмотрения дела, определяются арбитражным судом на основании требований и возражений лиц, участвующих в деле, в соответствии с подлежащими применению нормами материального права.","article_title":"Статья 65. Обязанность доказывания","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"71449ef1883f1a174e601d18b25f4e4154fd67b19035c892da8266406bbd840c"},{"code_id":"APK_RF","article_number":"66","version_date":"2002-07-24","article_text":"1. Доказательства представляются лицами, участвующими в деле.\n\nКопии документов, представленных в суд лицом, участвующим в деле, направляются им другим лицам, участвующим в деле, если у них эти документы отсутствуют.\n\nВ ходатайстве должно быть обозначено доказательство, указано, какие обстоятельства, имеющие значение для дела, могут быть установлены этим доказательством, указаны причины, препятствующие получению доказательства, и место его нахождения.\n\nПри удовлетворении ходатайства суд истребует соответствующее доказательство от лица, у которого оно находится.\n\nКопии документов, истребованных арбитражным судом по своей инициативе, направляются судом лицам, участвующим в деле, если у них эти документы отсутствуют.\n\nВ определении указываются срок и порядок представления доказательств.\n\nКопия определения направляется лицам, участвующим в деле, а также лицу, у которого находится истребуемое судом доказательство.\n\n10. О наложении судебного штрафа арбитражный суд выносит определение.\n\nВ определении о наложении судебного штрафа устанавливается новый срок, в течение которого должно быть представлено истребуемое доказательство.\n\nВ случае невыполнения этих требований в срок, указанный в определении о наложении судебного штрафа, арбитражный суд может повторно наложить штраф по правилам, предусмотренным частью 9 настоящей статьи.\n\n11. Наложение судебных штрафов не освобождает лицо, у которого находится истребуемое доказательство, от обязанности его представить в арбитражный суд.\n\n12. Определение арбитражного суда о наложении судебного штрафа может быть обжаловано.","article_title":"Статья 66. Представление и истребование доказательств","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a063ce9fdc7647d68aefb9229c1c1d7a2ceedbc562aa3f9eba852396cfd61cb7"},{"code_id":"APK_RF","article_number":"67","version_date":"2002-07-24","article_text":"1. Арбитражный суд принимает только те доказательства, которые имеют отношение к рассматриваемому делу.\n\n2. Арбитражный суд не принимает поступившие в суд документы, содержащие ходатайства о поддержке лиц, участвующих в деле, или оценку их деятельности, иные документы, не имеющие отношения к установлению обстоятельств по рассматриваемому делу, и отказывает в приобщении их к материалам дела. На отказ в приобщении к материалам дела таких документов суд указывает в протоколе судебного заседания.","article_title":"Статья 67. Относимость доказательств","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"368d6995c0e549993153efb1c99c438176fb4aa46b8940d0610111b914c94972"},{"code_id":"APK_RF","article_number":"68","version_date":"2002-07-24","article_text":"Обстоятельства дела, которые согласно закону должны быть подтверждены определенными доказательствами, не могут подтверждаться в арбитражном суде иными доказательствами.","article_title":"Статья 68. Допустимость доказательств","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b3d82838a4667d2950fd9b2ede934bfb40fa1cbe03e91d40a9ca951272b2cd58"},{"code_id":"APK_RF","article_number":"69","version_date":"2002-07-24","article_text":"1. Обстоятельства дела, признанные арбитражным судом общеизвестными, не нуждаются в доказывании.\n\n2. Обстоятельства, установленные вступившим в законную силу судебным актом арбитражного суда по ранее рассмотренному делу, не доказываются вновь при рассмотрении арбитражным судом другого дела, в котором участвуют те же лица.\n\n3. Вступившее в законную силу решение суда общей юрисдикции по ранее рассмотренному гражданскому делу обязательно для арбитражного суда, рассматривающего дело, по вопросам об обстоятельствах, установленных решением суда общей юрисдикции и имеющих отношение к лицам, участвующим в деле.","article_title":"Статья 69. Основания освобождения от доказывания","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"72f626fb0253a1c9d8e579606aee662d4af1e16247236f3bf9623ffce165deac"},{"code_id":"APK_RF","article_number":"7","version_date":"2002-07-24","article_text":"1. Правосудие в арбитражных судах осуществляется на началах равенства всех перед законом и судом независимо от пола, расы, национальности, языка, происхождения, имущественного и должностного положения, места жительства, отношения к религии, убеждений, принадлежности к общественным объединениям и других обстоятельств, равенства всех организаций перед законом и судом независимо от организационно-правовой формы, формы собственности, подчиненности, места нахождения и других обстоятельств.\n\n2. Арбитражный суд обеспечивает равную судебную защиту прав и законных интересов всех лиц, участвующих в деле.","article_title":"Статья 7. Равенство всех перед законом и судом","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5553c7933b16b5b835eae9f336b482874959122abebf143a61fd16aacce35dc9"},{"code_id":"APK_RF","article_number":"70","version_date":"2002-07-24","article_text":"1. Арбитражные суды первой и апелляционной инстанций на всех стадиях арбитражного процесса должны содействовать достижению сторонами соглашения в оценке обстоятельств в целом или в их отдельных частях, проявлять в этих целях необходимую инициативу, использовать свои процессуальные полномочия и авторитет органа судебной власти.\n\n2. Признанные сторонами в результате достигнутого между ними соглашения обстоятельства принимаются арбитражным судом в качестве фактов, не требующих дальнейшего доказывания.\n\nДостигнутое в судебном заседании или вне судебного заседания соглашение сторон по обстоятельствам удостоверяется их заявлениями в письменной форме и заносится в протокол судебного заседания.\n\n3. Признание стороной обстоят\n\nельств, на которых другая сторона основывает свои требования или возражения, освобождает другую сторону от необходимости доказывания таких обстоятельств.\n\nФакт признания сторонами обстоятельств заносится арбитражным судом в протокол судебного заседания и удостоверяется подписями сторон. Признание, изложенное в письменной форме, приобщается к материалам дела.\n\n4. Арбитражный суд не принимает признание стороной обстоятельств, если располагает доказательствами, дающими основание полагать, что признание такой стороной указанных обстоятельств совершено в целях сокрытия определенных фактов или под влиянием обмана, насилия, угрозы, заблуждения, на что арбитражным судом указывается в протоколе судебного заседания.\n\nВ этом случае данные обстоятельства подлежат доказыванию на общих основаниях.\n\n5. Обстоятельства, признанные и удостоверенные сторонами в порядке, установленном настоящей статьей, в случае их принятия арбитражным судом не проверяются им в ходе дальнейшего производства по делу.","article_title":"Статья 70. Освобождение от доказывания обстоятельств, признанных сторонами","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"96f0d35d3502e185327ce7a32b79c572d2e7aab7b709c03f430d6afcc69c0646"},{"code_id":"APK_RF","article_number":"71","version_date":"2002-07-24","article_text":"1. Арбитражный суд оценивает доказательства по своему внутреннему убеждению, основанному на всестороннем, полном, объективном и непосредственном исследовании имеющихся в деле доказательств.\n\n2. Арбитражный суд оценивает относимость, допустимость, достоверность каждого доказательства в отдельности, а также достаточность и взаимную связь доказательств в их совокупности.\n\n3. Доказательство признается арбитражным судом достоверным, если в результате его проверки и исследования выясняется, что содержащиеся в нем сведения соответствуют действительности.\n\n4. Каждое доказательство подлежит оценке арбитражным судом наряду с другими доказательствами.\n\n5. Никакие доказательства не имеют для арбитражного суда заранее установленной силы.\n\n6. Арбитражный суд не может считать доказанным факт, подтверждаемый только копией документа или иного письменного доказательства, если утрачен или не передан в суд оригинал документа, а копии этого документа, представленные лицами, участвующими в деле, не тождественны между собой и невозможно установить подлинное содержание первоисточника с помощью других доказательств.\n\n7. Результаты оценки доказательств суд отражает в судебном акте, содержащем мотивы принятия или отказа в принятии доказательств, представленных лицами, участвующими в деле, в обоснование своих требований и возражений.","article_title":"Статья 71. Оценка доказательств","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a2953fd7d9e167fb63debb52ba707ddf8c0b5889301c370db8018237a502bbd4"},{"code_id":"APK_RF","article_number":"72","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, имеющие основания опасаться, что представление в арбитражный суд необходимых доказательств станет невозможным или затруднительным, могут обратиться с заявлением об обеспечении этих доказательств.\n\nВ заявлении должны быть указаны доказательства, которые необходимо обеспечить, обстоятельства, для подтверждения которых необходимы эти доказательства, причины, побудившие обратиться с заявлением об их обеспечении.","article_title":"Статья 72. Обеспечение доказательств","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"468a14a8f232e4619950690f5e4102206ffdd2852485d44e52cb01841c36b27c"},{"code_id":"APK_RF","article_number":"73","version_date":"2002-07-24","article_text":"1. Арбитражный суд, рассматривающий дело, в случае невозможности получения доказательств, находящихся на территории другого субъекта Российской Федерации, в порядке, предусмотренном статьей 66 настоящего Кодекса, вправе поручить соответствующему арбитражному суду произвести определенные процессуальные действия.\n\n2. О поручении произвести определенные процессуальные действия выносится определение.\n\nВ определении кратко излагается содержание рассматриваемого дела, указываются обстоятельства, подлежащие выяснению, доказательства, которые должен получить арбитражный суд, выполняющий поручение.\n\nКопия определения направляется в суд, которому дано судебное поручение.\n\n3. Определение о судебном поручении обязательно для арбитражного суда, которому дано поручение, и должно быть выполнено не позднее чем в десятидневный срок со дня получения копии определения.","article_title":"Статья 73. Судебные поручения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bb9c831fd7347e4faab452392a242b6de0210127b30af1c0d10dd49b13b1903c"},{"code_id":"APK_RF","article_number":"74","version_date":"2002-07-24","article_text":"1. Судебное поручение выполняется в судебном заседании арбитражного суда по правилам, установленным настоящим Кодексом. Лица, участвующие в деле, извещаются о времени и месте судебного заседания. Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием к проведению заседания, если это не противоречит существу поручения.\n\n2. О выполнении судебного поручения выносится определение, которое со всеми материалами, собранными при выполнении судебного поручения, немедленно пересылается в арбитражный суд, направивший судебное поручение.\n\nПри невозможности выполнения судебного поручения по причинам, не зависящим от суда, на это указывается в определении.","article_title":"Статья 74. Порядок выполнения судебного поручения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b7b7a1c1b4ac09d15da91bc34037d3ece9181edac31d3520ff132692435015fd"},{"code_id":"APK_RF","article_number":"74.1","version_date":"2002-07-24","article_text":"1. Третейский суд с местом арбитража на территории Российской Федерации (за исключением третейского суда в рамках арбитража для разрешения конкретного спора) в случае возникновения необходимости получения доказательств, требующихся для разрешения спора, вправе обратиться в арбитражный суд субъекта Российской Федерации, на территории которого находятся истребуемые доказательства, с запросом о содействии в получении этих доказательств в порядке, установленном статьей 66 настоящего Кодекса. Запрос может быть выдан таким третейским судом стороне третейского разбирательства для непосредственного направления этого запроса в арбитражный суд указанной стороной третейского разбирательства.\n\n2. В запросе, указанном в части 1 настоящей статьи, указываются обстоятельства, подлежащие выяснению, а также доказательства, которые должен получить арбитражный суд, исполняющий запрос. Запрос направляется в арбитражный суд, в который он адресован.\n\n3. Запрос, указанный в части 1 настоящей статьи, может быть направлен для получения письменных доказательств, вещественных доказательств и иных документов и материалов в соответствии со статьями 75, 76 и 89 настоящего Кодекса.\n\n4. Запрос, указанный в части 1 настоящей статьи, подлежит исполнению не позднее чем в тридцатидневный срок со дня его получения арбитражным судом, в который он адресован. Запрос не подлежит исполнению в следующих случаях:\n\n1) запрос направлен для получения доказательств, не предусмотренных частью 3 настоящей статьи;\n\n2) исполнение запроса может нарушить права и законные интересы третьих лиц, не участвующих в третейском разбирательстве;\n\n3) запрос направлен в отношении спора, предусмотренного частью 2 статьи 33 настоящего Кодекса;\n\n4) запрос позволяет обеспечить доступ к информации, составляющей государственную тайну;\n\n5) запрос позволяет обеспечить доступ к информации, составляющей служебную, коммерческую, банковскую или иную охраняемую законом тайну, в отношении лиц, не участвующих в третейском разбирательстве.\n\n5. Об отказе в исполнении запроса, указанного в части 1 настоящей статьи, арбитражный суд, в который он направлен, выносит определение, которое пересылается в третейский суд, направивший запрос. Указанное определение не подлежит обжалованию.\n\n6. Запрос, указанный в части 1 настоящей статьи, исполняется в судебном заседании арбитражного суда по правилам, установленным настоящим Кодексом. Стороны третейского разбирательства извещаются о времени и месте судебного заседания. Неявка сторон третейского разбирательства, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием к проведению заседания, если это не противоречит существу запроса.\n\n7. Об исполнении запроса, указанного в части 1 настоящей статьи, выносится определение, которое со всеми материалами, собранными при исполнении запроса, в трехдневный срок пересылается в третейский суд, направивший запрос, либо передается стороне третейского разбирательства, представившей запрос третейского суда, если в запросе прямо оговорена возможность получения истребуемых доказательств стороной третейского разбирательства. При невозможности исполнения запроса, указанного в части 1 настоящей статьи, по не зависящим от арбитражного суда причинам на это указывается в определении.\n\n(Дополнение статьей - Федеральный закон от 29.12.2015 № 409-ФЗ)","article_title":"Статья 74.1. Запросы третейского суда о содействии в получении доказательств","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a38773c4674fc2fcddc243e658797db5fbeba35bad77894b37f39b00dd2d47aa"},{"code_id":"APK_RF","article_number":"75","version_date":"2002-07-24","article_text":"1. Письменными доказательствами являются содержащие сведения об обстоятельствах, имеющих значение для дела, договоры, акты, справки, деловая корреспонденция, иные документы, выполненные в форме цифровой, графической записи или иным способом, позволяющим установить достоверность документа.\n\n2. К письменным доказательствам относятся также протоколы судебных заседаний, протоколы совершения отдельных процессуальных действий и приложения к ним.\n\nЕсли копии документов представлены в арбитражный суд в электронном виде, суд может потребовать представления оригиналов этих документов.\n\n(Часть в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 75. Письменные доказательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8446ff2fd09238b5a20c2924a5bbdd0b16e8e66205c57143281f0f360ce8b232"},{"code_id":"APK_RF","article_number":"76","version_date":"2002-07-24","article_text":"1. Вещественными доказательствами являются предметы, которые своими внешним видом, свойствами, местом нахождения или иными признаками могут служить средством установления обстоятельств, имеющих значение для дела.\n\n2. О приобщении вещественных доказательств к делу арбитражный суд выносит определение.","article_title":"Статья 76. Вещественные доказательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0f6b12b157b90e2155f793c9954f65fdc5e8d9dfa82d919fb216053b8e31dc6f"},{"code_id":"APK_RF","article_number":"77","version_date":"2002-07-24","article_text":"1. Вещественные доказательства хранятся по месту их нахождения. Они должны быть подробно описаны, опечатаны, а в случае необходимости засняты на фото- или видеопленку.\n\n2. Вещественные доказательства могут храниться в арбитражном суде, если суд признает это необходимым.\n\n3. Расходы на хранение вещественных доказательств распределяются между сторонами в соответствии с правилами, установленными статьей 110 настоящего Кодекса.\n\n4. Арбитражный суд и хранитель принимают меры по сохранению вещественных доказательств в неизменном состоянии.","article_title":"Статья 77. Хранение вещественных доказательств","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ffe58164fe5c4d358a37e79458cb780a1d76a7f2e3826b276ed9d304b8e0729d"},{"code_id":"APK_RF","article_number":"78","version_date":"2002-07-24","article_text":"1. Арбитражный суд может провести осмотр и исследование письменных и вещественных доказательств по месту их нахождения в случае невозможности или затруднительности доставки в суд.\n\nО проведении осмотра и исследования на месте выносится определение.\n\n2. Осмотр и исследование письменных и вещественных доказательств проводятся арбитражным судом с извещением лиц, участвующих в деле, о месте и времени осмотра и исследования. Неявка надлежащим образом извещенных лиц не препятствует проведению осмотра и исследования.\n\n3. В случае необходимости для участия в осмотре и исследовании письменных и вещественных доказательств арбитражным судом могут быть вызваны эксперты и свидетели, а также осуществлены фотографирование, аудио- и видеозапись.\n\n4. Непосредственно в процессе осмотра и исследования письменных и вещественных доказательств по месту их нахождения арбитражным судом составляется протокол в порядке, установленном статьей 155 настоящего Кодекса. К протоколу прилагаются составленные или проверенные при осмотре документы, сделанные фотоснимки, аудио- и видеозаписи.","article_title":"Статья 78. Осмотр и исследование письменных и вещественных доказательств по месту их нахождения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bd1e279ff0c09be1a74cd931d8e562044b474b3ec53892df21671ef66b6331ab"},{"code_id":"APK_RF","article_number":"79","version_date":"2002-07-24","article_text":"1. Вещественные доказательства, подвергающиеся быстрой порче, немедленно осматриваются и исследуются арбитражным судом по месту их нахождения. После осмотра они подлежат реализации в установленном порядке.\n\n2. О месте и времени осмотра и исследования вещественных доказательств, подвергающихся быстрой порче, лица, участвующие в деле, извещаются арбитражным судом. Неявка надлежащим образом извещенных лиц не препятствует осмотру и исследованию вещественных доказательств, подвергающихся быстрой порче.\n\n3. Осмотр и исследование вещественных доказательств, подвергающихся быстрой порче, проводятся в порядке, установленном статьей 78 настоящего Кодекса, с учетом особенностей, предусмотренных настоящей статьей.","article_title":"Статья 79. Осмотр и исследование вещественных доказательств, подвергающихся быстрой порче","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"78ecaa5736fbcb0b8f688a6c57c96c9dbb31e6a0aaea0b5e3dc78fbe82155d06"},{"code_id":"APK_RF","article_number":"8","version_date":"2002-07-24","article_text":"1. Судопроизводство в арбитражном суде осуществляется на основе равноправия сторон.\n\n2. Стороны пользуются равными правами на заявление отводов и ходатайств, представление доказательств, участие в их исследовании, выступление в судебных прениях, представление арбитражному суду своих доводов и объяснений, осуществление иных процессуальных прав и обязанностей, предусмотренных настоящим Кодексом.\n\n3. Арбитражный суд не вправе своими действиями ставить какую-либо из сторон в преимущественное положение, равно как и умалять права одной из сторон.","article_title":"Статья 8. Равноправие сторон","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e80889cf819dee2992b089cefc0c4953fa1aa26d6f4ed2e38bd0d1ebba42a67e"},{"code_id":"APK_RF","article_number":"80","version_date":"2002-07-24","article_text":"1. Вещественные доказательства, находящиеся в арбитражном суде, после их осмотра и исследования судом возвращаются лицам, от которых они были получены, если они не подлежат передаче другим лицам.\n\n2. Арбитражный суд вправе сохранить вещественные доказательства до принятия судебного акта, которым заканчивается рассмотрение дела, и возвратить их после вступления указанного судебного акта в законную силу.\n\n3. Предметы, которые согласно федеральному закону не могут находиться во владении отдельных лиц, передаются соответствующим организациям.\n\n4. По вопросам распоряжения вещественными доказательствами арбитражный суд выносит определение.","article_title":"Статья 80. Распоряжение вещественными доказательствами, находящимися в арбитражном суде","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6d286cfef65cfaaf8f5492edb5caf91405ce762435d9b8371470501663d556d6"},{"code_id":"APK_RF","article_number":"81","version_date":"2002-07-24","article_text":"1. Лицо, участвующее в деле, представляет арбитражному суду свои объяснения об известных ему обстоятельствах, имеющих значение для дела, в письменной или устной форме. По предложению суда лицо, участвующее в деле, может изложить свои объяснения в письменной форме.\n\nОбъяснения, изложенные в письменной форме, приобщаются к материалам дела.\n\n2. Объяснения, изложенные в письменной форме участвующими в деле лицами, оглашаются в судебном заседании.\n\nПосле оглашения объяснения, изложенного в письменной форме, лицо, представившее это объяснение, вправе дать относительно него необходимые пояснения, а также обязано ответить на вопросы других лиц, участвующих в деле, и арбитражного суда.","article_title":"Статья 81. Объяснения лиц, участвующих в деле","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1f8976cd6d3f7cf808fed3590fffe736db082469a19a9c88df5cd4dac5486817"},{"code_id":"APK_RF","article_number":"82","version_date":"2002-07-24","article_text":"1. Для разъяснения возникающих при рассмотрении дела вопросов, требующих специальных знаний, арбитражный суд назначает экспертизу по ходатайству лица, участвующего в деле, или с согласия лиц, участвующих в деле. В случае, если назначение экспертизы предписано законом или предусмотрено договором либо необходимо для проверки заявления о фальсификации представленного доказательства либо если необходимо проведение дополнительной или повторной экспертизы, арбитражный суд может назначить экспертизу по своей инициативе.\n\n2. Круг и содержание вопросов, по которым должна быть проведена экспертиза, определяются арбитражным судом. Лица, участвующие в деле, вправе представить в арбитражный суд вопросы, которые должны быть разъяснены при проведении экспертизы. Отклонение вопросов, представленных лицами, участвующими в деле, суд обязан мотивировать.\n\n3. Лица, участвующие в деле, вправе ходатайствовать о привлечении в качестве экспертов указанных ими лиц или о проведении экспертизы в конкретном экспертном учреждении, заявлять отвод эксперту; ходатайствовать о внесении в определение о назначении экспертизы дополнительных вопросов, поставленных перед экспертом; давать объяснения эксперту; знакомиться с заключением эксперта или сообщением о невозможности дать заключение; ходатайствовать о проведении дополнительной или повторной экспертизы.\n\n4. О назначении экспертизы или об отклонении ходатайства о назначении экспертизы арбитражный суд выносит определение.\n\nВ определении о назначении экспертизы указываются основания для назначения экспертизы; фамилия, имя и отчество эксперта или наименование экспертного учреждения, в котором должна быть проведена экспертиза; вопросы, поставленные перед экспертом; материалы и документы, предоставляемые в распоряжение эксперта; срок, в течение которого должна быть проведена экспертиза и должно быть представлено заключение в арбитражный суд.\n\nВ определении также указывается на предупреждение эксперта об уголовной ответственности за дачу заведомо ложного заключения.","article_title":"Статья 82. Назначение экспертизы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"51e43caba430569ce614804f71dcb3479b5191537a0e2f29fc0683cb32d5fc00"},{"code_id":"APK_RF","article_number":"83","version_date":"2002-07-24","article_text":"1. Экспертиза проводится государственными судебными экспертами по поручению руководителя государственного судебно-экспертного учреждения и иными экспертами из числа лиц, обладающих специальными знаниями, в соответствии с федеральным законом.\n\nПроведение экспертизы может быть поручено нескольким экспертам.\n\n2. Лица, участвующие в деле, могут присутствовать при проведен\n\nии экспертизы, за исключением случаев, если такое присутствие способно помешать нормальной работе экспертов, но не вправе вмешиваться в ход исследований.\n\n3. При составлении экспертом заключения и на стадии совещания экспертов и формулирования выводов, если судебная экспертиза проводится комиссией экспертов, присутствие участников арбитражного процесса не допускается.","article_title":"Статья 83. Порядок проведения экспертизы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7e6ac255919a254e3581369e5e9e2e75ee7cdb7da263687fdc3fb51974aa31cc"},{"code_id":"APK_RF","article_number":"84","version_date":"2002-07-24","article_text":"1. Комиссионная экспертиза проводится не менее чем двумя экспертами одной специальности. Комиссионный характер экспертизы определяется арбитражным судом.\n\n2. В случае, если по результатам проведенных исследований мнения экспертов по поставленным вопросам совпадают, экспертами составляется единое заключение. В случае возникновения разногласий каждый из экспертов, участвовавших в проведении экспертизы, дает отдельное заключение по вопросам, вызвавшим разногласия экспертов.","article_title":"Статья 84. Комиссионная экспертиза","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b424742e448c83444477f8d2339107dfec844b561542a4f698d0fc7753aec85e"},{"code_id":"APK_RF","article_number":"85","version_date":"2002-07-24","article_text":"1. Комплексная экспертиза проводится не менее чем двумя экспертами разных специальностей.\n\n2. В заключении экспертов указывается, какие исследования и в каком объеме провел каждый эксперт, какие факты он установил и к каким выводам пришел. Каждый эксперт, участвовавший в проведении комплексной экспертизы, подписывает ту часть заключения, которая содержит описание проведенных им исследований, и несет за нее ответственность.\n\n3. Общий вывод делают эксперты, компетентные в оценке полученных результатов и формулировании данного вывода. В случае возникновения разногласий между экспертами результаты исследований оформляются в соответствии с частью 2 статьи 84 настоящего Кодекса.","article_title":"Статья 85. Комплексная экспертиза","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"096ea07a2d3023dd361e84e69a2c4dc54aec2ee74854e38eb92f666cbdcec83f"},{"code_id":"APK_RF","article_number":"86","version_date":"2002-07-24","article_text":"1. На основании проведенных исследований и с учетом их результатов эксперт от своего имени или комиссия экспертов дает заключение в письменной форме и подписывает его.\n\n2. В заключении эксперта или комиссии экспертов должны быть отражены:\n\n1) время и место проведения судебной экспертизы;\n\n2) основания для проведения судебной экспертизы;\n\n3) сведения о государственном судебно-экспертном учреждении, об эксперте (фамилия, имя, отчество, образование, специальность, стаж работы, ученая степень и ученое звание, занимаемая должность), которым поручено проведение судебной экспертизы;\n\n4) записи о предупреждении эксперта в соответствии с законодательством Российской Федерации об уголовной ответственности за дачу заведомо ложного заключения;\n\n5) вопросы, поставленные перед экспертом или комиссией экспертов;\n\n6) объекты исследований и материалы дела, предоставленные эксперту для проведения судебной экспертизы;\n\n7) содержание и результаты исследований с указанием примененных методов;\n\n8) оценка результатов исследований, выводы по поставленным вопросам и их обоснование;\n\n9) иные сведения в соответствии с федеральным законом.\n\nМатериалы и документы, иллюстрирующие заключение эксперта или комиссии экспертов, прилагаются к заключению и служат его составной частью.\n\nЕсли эксперт при проведении экспертизы установит обстоятельства, которые имеют значение для дела и по поводу которых ему не были поставлены вопросы, он вправе включить выводы об этих обстоятельствах в свое заключение.\n\n3. Заключение эксперта оглашается в судебном заседании и исследуется наряду с другими доказательствами по делу.\n\nПо ходатайству лица, участвующего в деле, или по инициативе арбитражного суда эксперт может быть вызван в судебное заседание.\n\nЭксперт после оглашения его заключения вправе дать по нему необходимые пояснения, а также обязан ответить на дополнительные вопросы лиц, участвующих в деле, и суда. Ответы эксперта на дополнительные вопросы заносятся в протокол судебного заседания.","article_title":"Статья 86. Заключение эксперта","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4879217535ae09b5370efb89c1fa0b02b0a7ce983a187b82f3d1fdd2779b7951"},{"code_id":"APK_RF","article_number":"87","version_date":"2002-07-24","article_text":"1. При недостаточной ясности или полноте заключения эксперта, а также при возникновении вопросов в отношении ранее исследованных обстоятельств дела может быть назначена дополнительная экспертиза, проведение которой поручается тому же или другому эксперту.\n\n2. В случае возникновения сомнений в обоснованности заключения эксперта или наличия противоречий в выводах эксперта или комиссии экспертов по тем же вопросам может быть назначена повторная экспертиза, проведение которой поручается другому эксперту или другой комиссии экспертов.","article_title":"Статья 87. Дополнительная и повторная экспертизы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"646bde5316b1de8b39d438a0829644aff0947d91bf0fd1b6d2d6364fc0f82139"},{"code_id":"APK_RF","article_number":"87.1","version_date":"2002-07-24","article_text":"1. В целях получения разъяснений, консультаций и выяснения профессионального мнения лиц, обладающих теоретическими и практическими познаниями по существу разрешаемого арбитражным судом спора, арбитражный суд может привлекать специалиста.\n\nСоветники аппарата специализированного арбитражного суда, обладающие квалификацией, соответствующей специализации суда, могут привлекаться в качестве специалистов.\n\n2. Специалист дает консультацию добросовестно и беспристрастно исходя из профессиональных знаний и внутреннего убеждения.\n\nКонсультация дается в устной форме без проведения специальных исследований, назначаемых на основании определения суда.\n\n3. В целях получения разъяснений и дополнений по оказанной консультации специалисту могут быть заданы вопросы судом и лицами, участвующими в деле.\n\n(Дополнение статьей - Федеральный закон от 08.12.2011 № 422-ФЗ)","article_title":"Статья 87.1. Консультация специалиста","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f96f93acf8b220773d4dd51b1ef859f08be8dc5af9977a146fa6b84829f95cf2"},{"code_id":"APK_RF","article_number":"88","version_date":"2002-07-24","article_text":"1. По ходатайству лица, участвующего в деле, арбитражный суд вызывает свидетеля для участия в арбитражном процессе.\n\nЛицо, ходатайствующее о вызове свидетеля, обязано указать, какие обстоятельства, имеющие значение для дела, может подтвердить свидетель, и сообщить суду его фамилию, имя, отчество и место жительства.\n\n2. Арбитражный суд по своей инициативе может вызвать в качестве свидетеля лицо, участвовавшее в составлении документа, исследуемого судом как письменное доказательство, либо в создании или изменении предмета, исследуемого судом как вещественное доказательство.\n\n3. Свидетель сообщает известные ему сведения устно. По предложению суда свидетель может изложить показания, данные устно, в письменной форме.\n\nПоказания свидетеля, изложенные в письменной форме, приобщаются к материалам дела.\n\n4. Не являются доказательствами сведения, сообщаемые свидетелем, если он не может указать источник своей осведомленности.","article_title":"Статья 88. Свидетельские показания","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2deb20fc5cb17a9d91557eaaab29c91d42d16a5bc8bca732dc436c0c4203baf"},{"code_id":"APK_RF","article_number":"89","version_date":"2002-07-24","article_text":"1. Иные документы и материалы допускаются в качестве доказательств, если содержат сведения об обстоятельствах, имеющих значение для правильного рассмотрения дела.\n\n2. Иные документы и материалы могут содержать сведения, зафиксированные как в письменной, так и в иной форме. К ним могут относиться материалы фото- и киносъемки, аудио- и видеозаписи и иные носители информации, полученные, истребованные или представленные в порядке, установленном настоящим Кодексом.\n\n3. Документы приобщаются к материалам дела и хранятся в арбитражном суде в течение всего срока хранения дела. По ходатайству лица, от которого они были получены, документы или их копии могут быть ему возвращены.","article_title":"Статья 89. Иные документы и материалы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"af81140a0d9c31aefe891973e80ef57200bb7faece36ccaa90ca869fac9a3372"},{"code_id":"APK_RF","article_number":"9","version_date":"2002-07-24","article_text":"1. Судопроизводство в арбитражном суде осуществляется на основе состязательности.\n\n2. Лица, участвующие в деле, вправе знать об аргументах друг друга до начала судебного разбирательства. Каждому лицу, участвующему в деле, гарантируется право представлять доказательства арбитражному суду и другой стороне по делу, обеспечивается право заявлять ходатайства, высказывать свои доводы и соображения, давать объяснения по всем возникающим в ходе рассмотрения дела вопросам, связанным с представлением доказательств. Лица, участвующие в деле, несут риск наступления последствий совершения или несовершения ими процессуальных действий.\n\n3. Арбитражный суд, сохраняя независимость, объективность и беспристрастность, осуществляет руководство процессом, разъясняет лицам, участвующим в деле, их права и обязанности, предупреждает о последствиях совершения или несовершения ими процессуальных действий, оказывает содействие в реализации их прав, создает условия для всестороннего и полного исследования доказательств, установления фактических обстоятельств и правильного применения законов и иных нормативных правовых актов при рассмотрении дела.","article_title":"Статья 9. Состязательность","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"47a440d6cb46dc5863411e60c1f1a4e4b23dbbced839c7b8399e555afdd673a4"},{"code_id":"APK_RF","article_number":"91","version_date":"2002-07-24","article_text":"1. Обеспечительными мерами могут быть:\n\n1) наложение ареста на денежные средства (в том числе денежные средства, которые будут поступать на банковский счет) или иное имущество, принадлежащие ответчику и находящиеся у него или других лиц; (В редакции Федерального закона от 19.07.2009 № 205-ФЗ)\n\n2) запрещение ответчику и другим лицам совершать определенные действия, касающиеся предмета спора;\n\n3) возложение на ответчика обязанности совершить определенные действия в целях предотвращения порчи, ухудшения состояния спорного имущества;\n\n4) передача спорного имущества на хранение истцу или другому лицу;\n\n5) приостановление взыскания по оспариваемому истцом исполнительному или иному документу, взыскание по которому производится в бесспорном (безакцептном) порядке;\n\n6) приостановление реализации имущества в случае предъявления иска об освобождении имущества от ареста.\n\nАрбитражным судом могут быть приняты иные обеспечительные меры, а также одновременно может быть принято несколько обеспечительных мер.\n\n2. Обеспечительные меры должны быть соразмерны заявленному требованию.","article_title":"Статья 91. Обеспечительные меры","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cb39c4b7209b7c7a567c508ca450e1940637ec43698fee4935a888e946c01957"},{"code_id":"APK_RF","article_number":"92","version_date":"2002-07-24","article_text":"1. Заявление об обеспечении иска может быть подано в арбитражный суд одновременно с исковым заявлением или в процессе производства по делу до принятия судебного акта, которым заканчивается рассмотрение дела по существу. Ходатайство об обеспечении иска может быть изложено в исковом заявлении.\n\nЗаявление об обеспечении иска, подаваемое в электронном виде, должно быть подписано усиленной квалифицированной электронной подписью. (Дополнение абзацем - Федеральный закон от 23.06.2016 № 220-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. В заявлении об обеспечении иска должны быть указаны:\n\n1) наименование арбитражного суда, в который подается заявление;\n\n2) наименования истца и ответчика, их адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) предмет спора;\n\n4) размер имущественных требований;\n\n5) обоснование причины обращения с заявлением об обеспечении иска;\n\n6) обеспечительная мера, которую просит принять истец;\n\n7) перечень прилагаемых документов.\n\nВ заявлении об обеспечении иска могут быть также указаны встречное обеспечение и иные сведения, в том числе номера телефонов, факсов, адреса электронной почты лиц, участвующих в деле.\n\n3. Заявление об обеспечении иска подписывается лицом, участвующим в деле, или его представителем.\n\nК заявлению, подписанному представителем, прилагается доверенность или иной подтверждающий полномочия на его подписание документ.\n\n4. В случае, если ходатайство об обеспечении иска изложено в исковом заявлении, в этом ходатайстве должны быть указаны сведения, предусмотренные пунктами 5 и 6 части 2 настоящей статьи.\n\n5. К заявлению стороны третейского разбирательства об обеспечении иска прилагаются заверенная председателем постоянно действующего третейского суда копия искового заявления, принятого к рассмотрению третейским судом, или нотариально удостоверенная копия такого заявления и заверенная надлежащим образом копия соглашения о третейском разбирательстве.\n\n6. К заявлению об обеспечении иска, если оно в соответствии с настоящим Кодексом оплачивается государственной пошлиной, прилагается документ, подтверждающий ее уплату.","article_title":"Статья 92. Заявление об обеспечении иска","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8f3ccc31017fa785ee353b8d03ba466102ac68c0651d98c8ea03eb161a83c7e9"},{"code_id":"APK_RF","article_number":"93","version_date":"2002-07-24","article_text":"Копия определения об отказе в обеспечении иска направляется лицу, обратившемуся с заявлением об обеспечении иска.","article_title":"Статья 93. Порядок рассмотрения заявления об обеспечении иска","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"46a1d81de5c9c39ed81a7be93ef32e5d66289e0747ff9aa55c5a902102eaa11c"},{"code_id":"APK_RF","article_number":"94","version_date":"2002-07-24","article_text":"1. Арбитражный суд, допуская обеспечение иска, по ходатайству ответчика может потребовать от обратившегося с заявлением об обеспечении иска лица или предложить ему по собственной инициативе предоставить обеспечение возмещения возможных для ответчика убытков (встречное обеспечение) путем внесения на депозитный счет суда денежных средств в размере, предложенном судом, либо предоставления банковской гарантии, поручительства или иного финансового обеспечения на ту же сумму. Размер встречного обеспечения может быть установлен в пределах имущественных требований истца, указанных в его заявлении, а также суммы процентов от этих требований. Размер встречного обеспечения не может быть менее половины размера имущественных требований.\n\n2. Встречное обеспечение может быть предоставлено также ответчиком взамен мер по обеспечению иска о взыскании денежной суммы путем внесения на депозитный счет арбитражного суда денежных средств в размере требований истца.\n\n3. О встречном обеспечении арбитражный суд выносит определение не позднее следующего дня после дня поступления в суд заявления об обеспечении иска.\n\nВ определении указываются размер встречного обеспечения и срок его предоставления, который не может превышать пятнадцать дней со дня вынесения определения.\n\nКопия определения направляется лицам, участвующим в деле, не позднее следующего дня после дня вынесения определения.\n\nОпределение о встречном обеспечении может быть обжаловано.\n\n4. В случае вынесения определения о встречном обеспечении арбитражный суд не рассматривает заявление об обеспечении иска до представления в арбитражный суд документа, подтверждающего произведенное встречное обеспечение.\n\n5. При представлении в арбитражный суд документа, подтверждающего произведенное встречное обеспечение, или по истечении указанного в определении суда срока его представления арбитражный суд не позднее следующего дня после дня поступления такого документа рассматривает заявление об обеспечении иска в порядке, установленном статьей 93 настоящего Кодекса.\n\n6. Неисполнение лицом, ходатайствующим об обеспечении иска, определения арбитражного суда о встречном обеспечении в срок, указанный в определении, может быть основанием для отказа в обеспечении иска.\n\n7. Представление ответчиком документа, подтверждающего произведенное им встречное обеспечение, является основанием для отказа в обеспечении иска или отмены обеспечения иска.","article_title":"Статья 94. Встречное обеспечение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2209bebdf56a3d45417f2fa7475c221382572e024a7104c1b43f6034b7df8e56"},{"code_id":"APK_RF","article_number":"95","version_date":"2002-07-24","article_text":"1. По ходатайству истца или ответчика допускается замена одной обеспечительной меры другой.\n\n2. Вопрос о замене одной обеспечительной меры другой разрешается арбитражным судом в судебном заседании не позднее следующего дня после дня поступления в суд ходатайства о замене одной обеспечительной меры другой по правилам, предусмотренным настоящим Кодексом.","article_title":"Статья 95. Замена одной обеспечительной меры другой","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e69c5a4f8e3d23a408b17bf1ee0a28164289779ccb778fad29a3bc4ea1fa7bd3"},{"code_id":"APK_RF","article_number":"96","version_date":"2002-07-24","article_text":"арантии, поручительства или иного финансового обеспечения на ту же сумму, он вправе обратиться в арбитражный суд, рассматривающий дело, с ходатайством об отмене обеспечительных мер, которое рассматривается в соответствии со статьей 93 настоящего Кодекса.","article_title":"Статья 96. Исполнение определения арбитражного суда об обеспечении иска","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93317ac8ebb3c546ca3d58661ba1f02620ecf4b300da3f1ca796cfaf73ca94df"},{"code_id":"APK_RF","article_number":"97","version_date":"2002-07-24","article_text":"1. Обеспечение иска по ходатайству лица, участвующего в деле, может быть отменено арбитражным судом, рассматривающим дело.\n\n2. Вопрос об отмене обеспечения иска разрешается в судебном заседании в пятидневный срок со дня поступления заявления в арбитражный суд в порядке, предусмотренном статьей 93 настоящего Кодекса.\n\n3. В случае представления ответчиком документа, подтверждающего произведенное им встречное обеспечение, вопрос об отмене обеспечения иска рассматривается арбитражным судом не позднее следующего дня после дня представления указанного документа.\n\n4. По результатам рассмотрения ходатайства об отмене обеспечения иска выносится определение.\n\nКопии определения направляются лицам, участвующим в деле, не позднее следующего дня после дня его вынесения. Копии определения об отмене обеспечения иска в зависимости от вида принятых мер направляются также в государственные органы, иные органы, осуществляющие государственную регистрацию имущества или прав на него.\n\n5. Определения арбитражного суда об отмене обеспечения иска и об отказе в отмене обеспечения иска могут быть обжалованы.\n\n6. Отказ в отмене обеспечения иска не препятствует повторному обращению с таким же ходатайством при появлении новых обстоятельств, обосновывающих необходимость отмены обеспечения иска.","article_title":"Статья 97. Отмена обеспечения иска арбитражным судом","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"89cc4cbcb37624bdcef2e841fa61594329ae258c34f3ce1da0eff923811bec99"}]$law7v004$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
